static SHARED_CATALOG: OnceLock<Mutex<SharedCatalog>> = OnceLock::new();

#[derive(Clone, Debug, PartialEq, Eq)]
struct Column {
    name: String,
    oid: u32,
    type_size: i16,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct ErrorField {
    code: &'static str,
    message: &'static str,
    position: Option<&'static str>,
}

fn text_column(name: &str) -> Column {
    Column {
        name: name.to_string(),
        oid: gpu_db_protocol::SqlType::Text.postgres_oid(),
        type_size: gpu_db_protocol::SqlType::Text.type_size(),
    }
}

fn int4_column(name: &str) -> Column {
    Column {
        name: name.to_string(),
        oid: gpu_db_protocol::SqlType::Int4.postgres_oid(),
        type_size: gpu_db_protocol::SqlType::Int4.type_size(),
    }
}

fn int8_column(name: &str) -> Column {
    Column {
        name: name.to_string(),
        oid: 20,
        type_size: 8,
    }
}

fn numeric_column(name: &str) -> Column {
    Column {
        name: name.to_string(),
        oid: 1700,
        type_size: -1,
    }
}

fn bool_column(name: &str) -> Column {
    Column {
        name: name.to_string(),
        oid: 16,
        type_size: 1,
    }
}

/// Result-set [`Column`] metadata for a declared column type. Maps each storable
/// `SqlType` to its wire OID/size via the per-type helpers above.
fn column_for_sql_type(ty: gpu_db_protocol::SqlType, name: &str) -> Column {
    match ty {
        gpu_db_protocol::SqlType::Int2 => Column {
            name: name.to_string(),
            oid: gpu_db_protocol::SqlType::Int2.postgres_oid(),
            type_size: gpu_db_protocol::SqlType::Int2.type_size(),
        },
        gpu_db_protocol::SqlType::Int4 => int4_column(name),
        gpu_db_protocol::SqlType::Int8 => int8_column(name),
        gpu_db_protocol::SqlType::Numeric { .. } => numeric_column(name),
        gpu_db_protocol::SqlType::Bool => bool_column(name),
        gpu_db_protocol::SqlType::Text => text_column(name),
        gpu_db_protocol::SqlType::Date => Column {
            name: name.to_string(),
            oid: gpu_db_protocol::SqlType::Date.postgres_oid(),
            type_size: gpu_db_protocol::SqlType::Date.type_size(),
        },
        gpu_db_protocol::SqlType::Timestamp => Column {
            name: name.to_string(),
            oid: gpu_db_protocol::SqlType::Timestamp.postgres_oid(),
            type_size: gpu_db_protocol::SqlType::Timestamp.type_size(),
        },
        gpu_db_protocol::SqlType::Uuid => Column {
            name: name.to_string(),
            oid: gpu_db_protocol::SqlType::Uuid.postgres_oid(),
            type_size: gpu_db_protocol::SqlType::Uuid.type_size(),
        },
    }
}

fn copy_parse_error_field(error: CopyParseError) -> ErrorField {
    ErrorField {
        code: error.postgres_code(),
        message: error.postgres_message(),
        position: None,
    }
}

fn sql_value_matches_type(value: &SqlValue, ty: gpu_db_protocol::SqlType) -> bool {
    matches!(
        (value, ty),
        (SqlValue::Int4(_), gpu_db_protocol::SqlType::Int4)
            | (SqlValue::Text(_), gpu_db_protocol::SqlType::Text)
    )
}

fn column_default_matches_type(value: &ColumnDefault, ty: gpu_db_protocol::SqlType) -> bool {
    match value {
        ColumnDefault::Literal(value) => sql_value_matches_type(value, ty),
        ColumnDefault::SequenceNextVal { .. } => ty == gpu_db_protocol::SqlType::Int4,
    }
}

fn compare_sql_values(left: &SqlValue, right: &SqlValue) -> std::cmp::Ordering {
    use gpu_db_protocol::Decimal128;
    match (left, right) {
        // smallint widens to int4 for every comparison (PG's numeric tower); recurse widened.
        (SqlValue::Int2(left), right) => {
            compare_sql_values(&SqlValue::Int4(i32::from(*left)), right)
        }
        (left, SqlValue::Int2(right)) => {
            compare_sql_values(left, &SqlValue::Int4(i32::from(*right)))
        }
        (SqlValue::Int4(left), SqlValue::Int4(right)) => left.cmp(right),
        (SqlValue::Int8(left), SqlValue::Int8(right)) => left.cmp(right),
        (SqlValue::Int4(left), SqlValue::Int8(right)) => i64::from(*left).cmp(right),
        (SqlValue::Int8(left), SqlValue::Int4(right)) => left.cmp(&i64::from(*right)),
        // Numeric is now a fixed-point Decimal128: compare scale-aligned (1.0 == 1.00), and
        // promote an integer to a scale-0 decimal for cross-type comparison.
        (SqlValue::Numeric(left), SqlValue::Numeric(right)) => left.cmp(right),
        (SqlValue::Int4(left), SqlValue::Numeric(right)) => {
            Decimal128::new(i128::from(*left), 0).cmp(right)
        }
        (SqlValue::Int8(left), SqlValue::Numeric(right)) => {
            Decimal128::new(i128::from(*left), 0).cmp(right)
        }
        (SqlValue::Numeric(left), SqlValue::Int4(right)) => {
            left.cmp(&Decimal128::new(i128::from(*right), 0))
        }
        (SqlValue::Numeric(left), SqlValue::Int8(right)) => {
            left.cmp(&Decimal128::new(i128::from(*right), 0))
        }
        (SqlValue::Bool(left), SqlValue::Bool(right)) => left.cmp(right),
        (SqlValue::Text(left), SqlValue::Text(right)) => left.cmp(right),
        (
            SqlValue::Int4(_) | SqlValue::Int8(_) | SqlValue::Numeric(_),
            SqlValue::Bool(_) | SqlValue::Text(_),
        ) => std::cmp::Ordering::Less,
        (SqlValue::Bool(_), SqlValue::Int4(_) | SqlValue::Int8(_) | SqlValue::Numeric(_)) => {
            std::cmp::Ordering::Greater
        }
        (SqlValue::Bool(_), SqlValue::Text(_)) => std::cmp::Ordering::Less,
        (
            SqlValue::Text(_),
            SqlValue::Int4(_) | SqlValue::Int8(_) | SqlValue::Numeric(_) | SqlValue::Bool(_),
        ) => std::cmp::Ordering::Greater,
        // Date is its own ordering tier (it sorts after the other types); same-type dates compare by
        // their day count. Cross-type date comparisons are type errors the engine rejects upstream.
        (SqlValue::Date(left), SqlValue::Date(right)) => left.cmp(right),
        (
            SqlValue::Int4(_)
            | SqlValue::Int8(_)
            | SqlValue::Numeric(_)
            | SqlValue::Bool(_)
            | SqlValue::Text(_),
            SqlValue::Date(_),
        ) => std::cmp::Ordering::Less,
        (
            SqlValue::Date(_),
            SqlValue::Int4(_)
            | SqlValue::Int8(_)
            | SqlValue::Numeric(_)
            | SqlValue::Bool(_)
            | SqlValue::Text(_),
        ) => std::cmp::Ordering::Greater,
        // Timestamp is the last tier (sorts after date); same-type compares by microsecond count.
        (SqlValue::Timestamp(left), SqlValue::Timestamp(right)) => left.cmp(right),
        (
            SqlValue::Int4(_)
            | SqlValue::Int8(_)
            | SqlValue::Numeric(_)
            | SqlValue::Bool(_)
            | SqlValue::Text(_)
            | SqlValue::Date(_),
            SqlValue::Timestamp(_),
        ) => std::cmp::Ordering::Less,
        (
            SqlValue::Timestamp(_),
            SqlValue::Int4(_)
            | SqlValue::Int8(_)
            | SqlValue::Numeric(_)
            | SqlValue::Bool(_)
            | SqlValue::Text(_)
            | SqlValue::Date(_),
        ) => std::cmp::Ordering::Greater,
        // Uuid is the final tier; same-type compares byte-wise (PG's uuid order).
        (SqlValue::Uuid(left), SqlValue::Uuid(right)) => left.cmp(right),
        (
            SqlValue::Int4(_)
            | SqlValue::Int8(_)
            | SqlValue::Numeric(_)
            | SqlValue::Bool(_)
            | SqlValue::Text(_)
            | SqlValue::Date(_)
            | SqlValue::Timestamp(_),
            SqlValue::Uuid(_),
        ) => std::cmp::Ordering::Less,
        (
            SqlValue::Uuid(_),
            SqlValue::Int4(_)
            | SqlValue::Int8(_)
            | SqlValue::Numeric(_)
            | SqlValue::Bool(_)
            | SqlValue::Text(_)
            | SqlValue::Date(_)
            | SqlValue::Timestamp(_),
        ) => std::cmp::Ordering::Greater,
    }
}

fn select_filter_matches(left: &SqlValue, op: SelectFilterOp, right: &SqlValue) -> bool {
    match op {
        SelectFilterOp::Eq => left == right,
        SelectFilterOp::Lt => compare_sql_values(left, right).is_lt(),
        SelectFilterOp::Lte => !compare_sql_values(left, right).is_gt(),
        SelectFilterOp::Gt => compare_sql_values(left, right).is_gt(),
        SelectFilterOp::Gte => !compare_sql_values(left, right).is_lt(),
        SelectFilterOp::LikePrefix => match (left, right) {
            (SqlValue::Text(left), SqlValue::Text(prefix)) => left.starts_with(prefix),
            _ => false,
        },
    }
}

fn row_matches_select_filters(
    table: &Table,
    row: &[SqlValue],
    select: &gpu_db_protocol::Select,
) -> Result<bool, ErrorField> {
    let filter_groups = if select.filter_groups.is_empty() {
        if select.filters.is_empty() {
            select
                .filter
                .iter()
                .cloned()
                .map(|filter| vec![filter])
                .collect::<Vec<_>>()
        } else {
            vec![select.filters.clone()]
        }
    } else {
        select.filter_groups.clone()
    };

    if filter_groups.is_empty() {
        return Ok(true);
    }

    for filters in filter_groups {
        let mut group_matches = true;
        for filter in filters {
            let Some(idx) = table
                .columns
                .iter()
                .position(|column| column.def.name == filter.column)
            else {
                return Err(ErrorField {
                    code: "42703",
                    message: "column does not exist",
                    position: None,
                });
            };
            if !select_filter_matches(&row[idx], filter.op, &filter.value) {
                group_matches = false;
                break;
            }
        }
        if group_matches {
            return Ok(true);
        }
    }

    Ok(false)
}

fn row_matches_delete_filters(
    table: &Table,
    row: &[SqlValue],
    delete: &gpu_db_protocol::Delete,
) -> Result<bool, ErrorField> {
    let filter_groups = if delete.filter_groups.is_empty() {
        if delete.filters.is_empty() {
            delete
                .filter
                .iter()
                .cloned()
                .map(|filter| vec![filter])
                .collect::<Vec<_>>()
        } else {
            vec![delete.filters.clone()]
        }
    } else {
        delete.filter_groups.clone()
    };

    if filter_groups.is_empty() {
        return Err(ErrorField {
            code: "42601",
            message: "DELETE requires WHERE filters",
            position: None,
        });
    }

    for filters in filter_groups {
        let mut group_matches = true;
        for filter in filters {
            let Some(idx) = table
                .columns
                .iter()
                .position(|column| column.def.name == filter.column)
            else {
                return Err(ErrorField {
                    code: "42703",
                    message: "column does not exist",
                    position: None,
                });
            };
            if !sql_value_matches_type(&filter.value, table.columns[idx].def.ty) {
                return Err(ErrorField {
                    code: "42804",
                    message: "column type mismatch",
                    position: None,
                });
            }
            if !select_filter_matches(&row[idx], filter.op, &filter.value) {
                group_matches = false;
                break;
            }
        }
        if group_matches {
            return Ok(true);
        }
    }

    Ok(false)
}

fn grouped_row_matches_having(
    select: &gpu_db_protocol::Select,
    group_column: &str,
    group_value: &SqlValue,
    aggregate_name: &'static str,
    aggregate_value: &SqlValue,
) -> Result<bool, ErrorField> {
    if select.having_groups.is_empty() {
        return Ok(true);
    }

    for filters in &select.having_groups {
        let mut group_matches = true;
        for filter in filters {
            let value = if filter.column == group_column {
                group_value
            } else if filter.column.eq_ignore_ascii_case(aggregate_name) {
                aggregate_value
            } else {
                return Err(ErrorField {
                    code: "0A000",
                    message: "HAVING must reference grouped column or aggregate result",
                    position: None,
                });
            };
            if !select_filter_matches(value, filter.op, &filter.value) {
                group_matches = false;
                break;
            }
        }
        if group_matches {
            return Ok(true);
        }
    }

    Ok(false)
}

fn execute_select_result(
    session: &Session,
    select: &gpu_db_protocol::Select,
) -> Result<SelectResult, ErrorField> {
    execute_select_result_inner(session, select, true)
}

fn execute_select_result_inner(
    session: &Session,
    select: &gpu_db_protocol::Select,
    enforce_relation_acl: bool,
) -> Result<SelectResult, ErrorField> {
    // Multi-key ORDER BY (`ORDER BY a, b, ...`) is GPU-only -- it runs on the general Expr executor's
    // bitonic-sort path (the consolidated server). This legacy pgwire handler sorts on the CPU off the
    // first key only, so rather than silently mis-order a multi-key request, reject it cleanly.
    if select.order_by.len() > 1 {
        return Err(ErrorField {
            code: "0A000",
            message: "multi-key ORDER BY is supported only on the GPU executor (consolidated server)",
            position: None,
        });
    }
    let Some(table) = session.tables.get(&select.table) else {
        if let Some(view) = session.views.get(&select.table) {
            if !select_is_plain_view_scan(select) {
                return Err(ErrorField {
                    code: "0A000",
                    message: "only plain SELECT * FROM view is supported for views",
                    position: None,
                });
            }
            if enforce_relation_acl {
                if let Some(error) =
                    object_access_permission_error(session, &select.table, TablePrivilege::Select)
                {
                    return Err(error);
                }
            }
            return execute_select_result_inner(session, &view.query, false);
        }
        if let Some(view) = session.materialized_views.get(&select.table) {
            if !select_is_plain_view_scan(select) {
                return Err(ErrorField {
                    code: "0A000",
                    message:
                        "only plain SELECT * FROM materialized view is supported for materialized views",
                    position: None,
                });
            }
            if enforce_relation_acl {
                if let Some(error) =
                    object_access_permission_error(session, &select.table, TablePrivilege::Select)
                {
                    return Err(error);
                }
            }
            return Ok(SelectResult {
                columns: view
                    .columns
                    .iter()
                    .map(|column| column_for_sql_type(column.def.ty, &column.def.name))
                    .collect(),
                rows: view
                    .rows
                    .iter()
                    .map(|row| {
                        row.iter()
                            .map(|value| Some(format_sql_value(value)))
                            .collect()
                    })
                    .collect(),
            });
        }
        return Err(ErrorField {
            code: "42P01",
            message: "relation does not exist",
            position: None,
        });
    };
    if enforce_relation_acl {
        if let Some(error) =
            object_access_permission_error(session, &select.table, TablePrivilege::Select)
        {
            return Err(error);
        }
    }
    if matches!(
        select.projection,
        SelectProjection::CountAll
            | SelectProjection::GroupedCount { .. }
            | SelectProjection::Sum { .. }
            | SelectProjection::GroupedSum { .. }
            | SelectProjection::Avg { .. }
            | SelectProjection::GroupedAvg { .. }
            | SelectProjection::Min { .. }
            | SelectProjection::GroupedMin { .. }
            | SelectProjection::Max { .. }
            | SelectProjection::GroupedMax { .. }
    ) {
        return execute_aggregate_select_result(table, select);
    }

    if select.group_by.is_some() {
        return Err(ErrorField {
            code: "0A000",
            message: "GROUP BY requires COUNT(*) projection",
            position: None,
        });
    }

    let selected_columns = match &select.projection {
        SelectProjection::All => table.columns.clone(),
        SelectProjection::Columns(columns) => {
            let mut selected = Vec::with_capacity(columns.len());
            for column in columns {
                let Some(def) = table
                    .columns
                    .iter()
                    .find(|candidate| candidate.def.name == *column)
                else {
                    return Err(ErrorField {
                        code: "42703",
                        message: "column does not exist",
                        position: None,
                    });
                };
                selected.push(def.clone());
            }
            selected
        }
        SelectProjection::CountAll
        | SelectProjection::GroupedCount { .. }
        | SelectProjection::Sum { .. }
        | SelectProjection::GroupedSum { .. }
        | SelectProjection::Avg { .. }
        | SelectProjection::GroupedAvg { .. }
        | SelectProjection::Min { .. }
        | SelectProjection::GroupedMin { .. }
        | SelectProjection::Max { .. }
        | SelectProjection::GroupedMax { .. }
        | SelectProjection::GroupedAggregates { .. } => unreachable!(),
    };
    if select.distinct {
        match &select.projection {
            SelectProjection::All => {
                return Err(ErrorField {
                    code: "0A000",
                    message: "SELECT DISTINCT * is unsupported",
                    position: None,
                });
            }
            SelectProjection::Columns(columns) => {
                if let Some(order) = select.order_by.first() {
                    if !columns.iter().any(|column| column == &order.column) {
                        return Err(ErrorField {
                            code: "0A000",
                            message: "SELECT DISTINCT ORDER BY must reference a selected column",
                            position: None,
                        });
                    }
                }
            }
            SelectProjection::CountAll
            | SelectProjection::GroupedCount { .. }
            | SelectProjection::Sum { .. }
            | SelectProjection::GroupedSum { .. }
            | SelectProjection::Avg { .. }
            | SelectProjection::GroupedAvg { .. }
            | SelectProjection::Min { .. }
            | SelectProjection::GroupedMin { .. }
            | SelectProjection::Max { .. }
            | SelectProjection::GroupedMax { .. }
            | SelectProjection::GroupedAggregates { .. } => unreachable!(),
        }
    }
    let selected_indexes = selected_columns
        .iter()
        .map(|selected| {
            table
                .columns
                .iter()
                .position(|column| column.def.name == selected.def.name)
                .expect("selected column came from table")
        })
        .collect::<Vec<_>>();
    let mut rows = Vec::new();
    for row in &table.rows {
        match row_matches_select_filters(table, row, select) {
            Ok(true) => rows.push(row.clone()),
            Ok(false) => {}
            Err(error) => return Err(error),
        }
    }
    if select.distinct {
        let mut projected = Vec::new();
        let mut seen = std::collections::BTreeSet::new();
        for row in &rows {
            let selected = selected_indexes
                .iter()
                .map(|idx| row[*idx].clone())
                .collect::<Vec<_>>();
            if seen.insert(selected.clone()) {
                projected.push(selected);
            }
        }
        if let Some(order) = select.order_by.first() {
            let Some(selected_order_idx) = selected_columns
                .iter()
                .position(|column| column.def.name == order.column)
            else {
                return Err(ErrorField {
                    code: "42703",
                    message: "column does not exist",
                    position: None,
                });
            };
            projected.sort_by(|left, right| {
                compare_sql_values(&left[selected_order_idx], &right[selected_order_idx])
            });
            if order.descending {
                projected.reverse();
            }
        }
        if let Some(offset) = select.offset {
            projected = projected.into_iter().skip(offset).collect();
        }
        if let Some(limit) = select.limit {
            projected.truncate(limit);
        }
        let columns = selected_columns
            .iter()
            .map(|column| column_for_sql_type(column.def.ty, &column.def.name))
            .collect::<Vec<_>>();
        let rows = projected
            .iter()
            .map(|row| {
                row.iter()
                    .map(|value| Some(format_sql_value(value)))
                    .collect()
            })
            .collect::<Vec<_>>();
        return Ok(SelectResult { columns, rows });
    }
    if let Some(order) = select.order_by.first() {
        let Some(idx) = table
            .columns
            .iter()
            .position(|column| column.def.name == order.column)
        else {
            return Err(ErrorField {
                code: "42703",
                message: "column does not exist",
                position: None,
            });
        };
        rows.sort_by(|left, right| compare_sql_values(&left[idx], &right[idx]));
        if order.descending {
            rows.reverse();
        }
    }
    if let Some(offset) = select.offset {
        rows = rows.into_iter().skip(offset).collect();
    }
    if let Some(limit) = select.limit {
        rows.truncate(limit);
    }
    let columns = selected_columns
        .iter()
        .map(|column| column_for_sql_type(column.def.ty, &column.def.name))
        .collect::<Vec<_>>();
    let rows = rows
        .iter()
        .map(|row| {
            selected_indexes
                .iter()
                .map(|idx| Some(format_sql_value(&row[*idx])))
                .collect::<Vec<_>>()
        })
        .collect::<Vec<_>>();
    Ok(SelectResult { columns, rows })
}

fn execute_function_result(
    session: &Session,
    call: &gpu_db_protocol::SelectFunction,
) -> Result<SelectResult, ErrorField> {
    if let Some(error) = schema_usage_permission_error(session, "public") {
        return Err(error);
    }
    let Some(function) = session.functions.get(&call.name) else {
        return Err(ErrorField {
            code: "42883",
            message: "function does not exist",
            position: None,
        });
    };
    if let Some(error) = function_access_permission_error(session, &call.name) {
        return Err(error);
    }
    let value = parse_bounded_sql_function_body(&function.body, function.return_type)?;
    let column = column_for_sql_type(function.return_type, &function.name);
    Ok(SelectResult {
        columns: vec![column],
        rows: vec![vec![Some(format_sql_value(&value))]],
    })
}

fn parse_bounded_sql_function_body(
    body: &str,
    return_type: SqlType,
) -> Result<SqlValue, ErrorField> {
    let Some(rest) = strip_keyword_prefix_case_insensitive(body.trim(), "SELECT") else {
        return Err(unsupported_function_body_error());
    };
    let literal = rest.trim();
    if literal.is_empty()
        || find_keyword_outside_quotes(literal, "FROM").is_some()
        || find_keyword_outside_quotes(literal, "WHERE").is_some()
        || find_keyword_outside_quotes(literal, "ORDER").is_some()
        || find_keyword_outside_quotes(literal, "GROUP").is_some()
        || find_keyword_outside_quotes(literal, "LIMIT").is_some()
        || find_keyword_outside_quotes(literal, "OFFSET").is_some()
        || literal.contains(',')
    {
        return Err(unsupported_function_body_error());
    }
    match return_type {
        SqlType::Int2 => literal
            .parse::<i16>()
            .map(SqlValue::Int2)
            .map_err(|_| unsupported_function_body_error()),
        SqlType::Int4 => literal
            .parse::<i32>()
            .map(SqlValue::Int4)
            .map_err(|_| unsupported_function_body_error()),
        SqlType::Int8 => literal
            .parse::<i64>()
            .map(SqlValue::Int8)
            .map_err(|_| unsupported_function_body_error()),
        SqlType::Numeric { scale, .. } => {
            gpu_db_protocol::Decimal128::parse_at_scale(literal, scale)
                .map(SqlValue::Numeric)
                .ok_or_else(unsupported_function_body_error)
        }
        SqlType::Bool => match literal.to_ascii_lowercase().as_str() {
            "true" | "t" => Ok(SqlValue::Bool(true)),
            "false" | "f" => Ok(SqlValue::Bool(false)),
            _ => Err(unsupported_function_body_error()),
        },
        SqlType::Text => parse_bounded_text_literal(literal)
            .map(SqlValue::Text)
            .ok_or_else(unsupported_function_body_error),
        SqlType::Date => gpu_db_protocol::datetime::parse_date(literal)
            .map(SqlValue::Date)
            .ok_or_else(unsupported_function_body_error),
        SqlType::Timestamp => gpu_db_protocol::datetime::parse_timestamp(literal)
            .map(SqlValue::Timestamp)
            .ok_or_else(unsupported_function_body_error),
        SqlType::Uuid => gpu_db_protocol::uuid::parse_uuid(literal)
            .map(SqlValue::Uuid)
            .ok_or_else(unsupported_function_body_error),
    }
}

fn strip_keyword_prefix_case_insensitive<'a>(input: &'a str, keyword: &str) -> Option<&'a str> {
    if input.len() < keyword.len() {
        return None;
    }
    let (head, tail) = input.split_at(keyword.len());
    if !head.eq_ignore_ascii_case(keyword) {
        return None;
    }
    if tail
        .chars()
        .next()
        .is_some_and(|ch| ch == '_' || ch == '$' || ch.is_ascii_alphanumeric())
    {
        return None;
    }
    Some(tail)
}

fn find_keyword_outside_quotes(input: &str, keyword: &str) -> Option<usize> {
    let bytes = input.as_bytes();
    let keyword_bytes = keyword.as_bytes();
    let mut idx = 0;
    let mut in_quote = false;
    while idx < bytes.len() {
        if bytes[idx] == b'\'' {
            if in_quote && idx + 1 < bytes.len() && bytes[idx + 1] == b'\'' {
                idx += 2;
                continue;
            }
            in_quote = !in_quote;
            idx += 1;
            continue;
        }
        if !in_quote
            && idx + keyword_bytes.len() <= bytes.len()
            && input[idx..idx + keyword_bytes.len()].eq_ignore_ascii_case(keyword)
        {
            let before_ok = idx == 0
                || !bytes[idx - 1].is_ascii_alphanumeric()
                    && bytes[idx - 1] != b'_'
                    && bytes[idx - 1] != b'$';
            let after_idx = idx + keyword_bytes.len();
            let after_ok = after_idx == bytes.len()
                || !bytes[after_idx].is_ascii_alphanumeric()
                    && bytes[after_idx] != b'_'
                    && bytes[after_idx] != b'$';
            if before_ok && after_ok {
                return Some(idx);
            }
        }
        idx += 1;
    }
    None
}

fn parse_bounded_text_literal(input: &str) -> Option<String> {
    let bytes = input.as_bytes();
    if bytes.len() < 2 || bytes.first() != Some(&b'\'') || bytes.last() != Some(&b'\'') {
        return None;
    }
    let inner = &input[1..input.len() - 1];
    let mut result = String::new();
    let mut chars = inner.chars().peekable();
    while let Some(ch) = chars.next() {
        if ch == '\'' {
            if chars.peek() == Some(&'\'') {
                chars.next();
                result.push('\'');
            } else {
                return None;
            }
        } else {
            result.push(ch);
        }
    }
    Some(result)
}

fn unsupported_function_body_error() -> ErrorField {
    ErrorField {
        code: "0A000",
        message: "only literal SELECT bodies are supported for SQL function execution",
        position: None,
    }
}

fn session_view_depends_on(session: &Session, view: &str, target: &str) -> bool {
    let mut seen = BTreeSet::new();
    session_view_depends_on_inner(session, view, target, &mut seen)
}

fn session_view_depends_on_inner(
    session: &Session,
    view: &str,
    target: &str,
    seen: &mut BTreeSet<String>,
) -> bool {
    if view == target {
        return true;
    }
    if !seen.insert(view.to_string()) {
        return false;
    }
    let Some(view) = session.views.get(view) else {
        return false;
    };
    session_view_depends_on_inner(session, &view.query.table, target, seen)
}

fn session_view_has_dependents(session: &Session, view: &str) -> bool {
    session
        .views
        .keys()
        .any(|candidate| candidate != view && session_view_depends_on(session, candidate, view))
}

fn select_is_plain_view_scan(select: &gpu_db_protocol::Select) -> bool {
    !select.distinct
        && matches!(select.projection, SelectProjection::All)
        && select.group_by.is_none()
        && select.having_groups.is_empty()
        && select.filter.is_none()
        && select.filters.is_empty()
        && select.filter_groups.is_empty()
        && select.order_by.is_empty()
        && select.limit.is_none()
        && select.offset.is_none()
}

fn execute_aggregate_select_result(
    table: &Table,
    select: &gpu_db_protocol::Select,
) -> Result<SelectResult, ErrorField> {
    let mut rows = Vec::new();
    for row in &table.rows {
        match row_matches_select_filters(table, row, select) {
            Ok(true) => rows.push(row.clone()),
            Ok(false) => {}
            Err(error) => return Err(error),
        }
    }
    if !select.having_groups.is_empty() && select.group_by.is_none() {
        return Err(ErrorField {
            code: "0A000",
            message: "HAVING requires GROUP BY",
            position: None,
        });
    }

    match &select.projection {
        // GroupedAggregates (N aggregates per group) is produced only by the engine Expr parser, not
        // the wire-protocol parser that feeds this handler.
        SelectProjection::GroupedAggregates { .. } => unreachable!(),
        SelectProjection::CountAll => {
            if select.group_by.is_some() {
                return Err(ErrorField {
                    code: "0A000",
                    message: "GROUP BY requires grouped COUNT(*) projection",
                    position: None,
                });
            }
            if let Some(order) = select.order_by.first() {
                if !order.column.eq_ignore_ascii_case("count") {
                    return Err(ErrorField {
                        code: "0A000",
                        message: "COUNT(*) ORDER BY only supports count",
                        position: None,
                    });
                }
            }
            let mut aggregate_rows = vec![vec![Some(rows.len().to_string())]];
            if let Some(offset) = select.offset {
                aggregate_rows = aggregate_rows.into_iter().skip(offset).collect();
            }
            if let Some(limit) = select.limit {
                aggregate_rows.truncate(limit);
            }
            Ok(SelectResult {
                columns: vec![int8_column("count")],
                rows: aggregate_rows,
            })
        }
        SelectProjection::GroupedCount { column } => {
            let Some(group_by) = &select.group_by else {
                return Err(ErrorField {
                    code: "0A000",
                    message: "grouped COUNT(*) requires GROUP BY",
                    position: None,
                });
            };
            if group_by != column {
                return Err(ErrorField {
                    code: "0A000",
                    message: "GROUP BY column must match grouped COUNT(*) projection",
                    position: None,
                });
            }
            let Some(group_idx) = table
                .columns
                .iter()
                .position(|candidate| candidate.def.name == *column)
            else {
                return Err(ErrorField {
                    code: "42703",
                    message: "column does not exist",
                    position: None,
                });
            };
            let mut counts: BTreeMap<SqlValue, usize> = BTreeMap::new();
            for row in rows {
                *counts.entry(row[group_idx].clone()).or_default() += 1;
            }
            let mut grouped = counts.into_iter().collect::<Vec<_>>();
            grouped = grouped
                .into_iter()
                .filter_map(|(group_value, count)| {
                    let aggregate = SqlValue::Int8(count as i64);
                    match grouped_row_matches_having(
                        select,
                        column,
                        &group_value,
                        "count",
                        &aggregate,
                    ) {
                        Ok(true) => Some(Ok((group_value, count))),
                        Ok(false) => None,
                        Err(error) => Some(Err(error)),
                    }
                })
                .collect::<Result<Vec<_>, _>>()?;
            if let Some(order) = select.order_by.first() {
                if order.column == *column {
                    grouped.sort_by(|(left, _), (right, _)| compare_sql_values(left, right));
                } else if order.column.eq_ignore_ascii_case("count") {
                    grouped.sort_by(|(left_value, left_count), (right_value, right_count)| {
                        left_count
                            .cmp(right_count)
                            .then_with(|| compare_sql_values(left_value, right_value))
                    });
                } else {
                    return Err(ErrorField {
                        code: "0A000",
                        message: "GROUP BY ORDER BY must reference grouped column or count",
                        position: None,
                    });
                }
                if order.descending {
                    grouped.reverse();
                }
            }
            if let Some(offset) = select.offset {
                grouped = grouped.into_iter().skip(offset).collect();
            }
            if let Some(limit) = select.limit {
                grouped.truncate(limit);
            }
            let group_column = table
                .columns
                .get(group_idx)
                .expect("group column index came from table");
            let columns = vec![
                column_for_sql_type(group_column.def.ty, &group_column.def.name),
                int8_column("count"),
            ];
            let rows = grouped
                .into_iter()
                .map(|(value, count)| vec![Some(format_sql_value(&value)), Some(count.to_string())])
                .collect();
            Ok(SelectResult { columns, rows })
        }
        SelectProjection::Sum { column } => {
            if select.group_by.is_some() {
                return Err(ErrorField {
                    code: "0A000",
                    message: "GROUP BY requires grouped SUM projection",
                    position: None,
                });
            }
            if let Some(order) = select.order_by.first() {
                if !order.column.eq_ignore_ascii_case("sum") {
                    return Err(ErrorField {
                        code: "0A000",
                        message: "SUM ORDER BY only supports sum",
                        position: None,
                    });
                }
            }
            let sum_idx = int4_column_index(table, column)?;
            let sum = rows
                .iter()
                .map(|row| int4_value(&row[sum_idx]))
                .collect::<Result<Vec<_>, _>>()?
                .into_iter()
                .map(i64::from)
                .sum::<i64>();
            let mut aggregate_rows = vec![vec![Some(sum.to_string())]];
            if let Some(offset) = select.offset {
                aggregate_rows = aggregate_rows.into_iter().skip(offset).collect();
            }
            if let Some(limit) = select.limit {
                aggregate_rows.truncate(limit);
            }
            Ok(SelectResult {
                columns: vec![int8_column("sum")],
                rows: aggregate_rows,
            })
        }
        SelectProjection::GroupedSum {
            group_column,
            sum_column,
        } => {
            let Some(group_by) = &select.group_by else {
                return Err(ErrorField {
                    code: "0A000",
                    message: "grouped SUM requires GROUP BY",
                    position: None,
                });
            };
            if group_by != group_column {
                return Err(ErrorField {
                    code: "0A000",
                    message: "GROUP BY column must match grouped SUM projection",
                    position: None,
                });
            }
            let Some(group_idx) = table
                .columns
                .iter()
                .position(|candidate| candidate.def.name == *group_column)
            else {
                return Err(ErrorField {
                    code: "42703",
                    message: "column does not exist",
                    position: None,
                });
            };
            let sum_idx = int4_column_index(table, sum_column)?;
            let mut sums: BTreeMap<SqlValue, i64> = BTreeMap::new();
            for row in rows {
                let value = int4_value(&row[sum_idx])?;
                *sums.entry(row[group_idx].clone()).or_default() += i64::from(value);
            }
            let mut grouped = sums.into_iter().collect::<Vec<_>>();
            grouped = grouped
                .into_iter()
                .filter_map(|(group_value, sum)| {
                    let aggregate = SqlValue::Int8(sum);
                    match grouped_row_matches_having(
                        select,
                        group_column,
                        &group_value,
                        "sum",
                        &aggregate,
                    ) {
                        Ok(true) => Some(Ok((group_value, sum))),
                        Ok(false) => None,
                        Err(error) => Some(Err(error)),
                    }
                })
                .collect::<Result<Vec<_>, _>>()?;
            if let Some(order) = select.order_by.first() {
                if order.column == *group_column {
                    grouped.sort_by(|(left, _), (right, _)| compare_sql_values(left, right));
                } else if order.column.eq_ignore_ascii_case("sum") {
                    grouped.sort_by(|(left_value, left_sum), (right_value, right_sum)| {
                        left_sum
                            .cmp(right_sum)
                            .then_with(|| compare_sql_values(left_value, right_value))
                    });
                } else {
                    return Err(ErrorField {
                        code: "0A000",
                        message: "GROUP BY ORDER BY must reference grouped column or sum",
                        position: None,
                    });
                }
                if order.descending {
                    grouped.reverse();
                }
            }
            if let Some(offset) = select.offset {
                grouped = grouped.into_iter().skip(offset).collect();
            }
            if let Some(limit) = select.limit {
                grouped.truncate(limit);
            }
            let group_column_def = table
                .columns
                .get(group_idx)
                .expect("group column index came from table");
            let columns = vec![
                column_for_sql_type(group_column_def.def.ty, &group_column_def.def.name),
                int8_column("sum"),
            ];
            let rows = grouped
                .into_iter()
                .map(|(value, sum)| vec![Some(format_sql_value(&value)), Some(sum.to_string())])
                .collect();
            Ok(SelectResult { columns, rows })
        }
        SelectProjection::Avg { column } => {
            if select.group_by.is_some() {
                return Err(ErrorField {
                    code: "0A000",
                    message: "GROUP BY requires grouped AVG projection",
                    position: None,
                });
            }
            if let Some(order) = select.order_by.first() {
                if !order.column.eq_ignore_ascii_case("avg") {
                    return Err(ErrorField {
                        code: "0A000",
                        message: "AVG ORDER BY only supports avg",
                        position: None,
                    });
                }
            }
            let avg_idx = int4_column_index_for_aggregate(table, column, "AVG")?;
            let mut sum = 0_i128;
            let mut count = 0_usize;
            for row in &rows {
                sum += i128::from(int4_value_for_aggregate(&row[avg_idx], "AVG")?);
                count += 1;
            }
            let mut aggregate_rows = vec![vec![average_text(sum, count)]];
            if let Some(offset) = select.offset {
                aggregate_rows = aggregate_rows.into_iter().skip(offset).collect();
            }
            if let Some(limit) = select.limit {
                aggregate_rows.truncate(limit);
            }
            Ok(SelectResult {
                columns: vec![numeric_column("avg")],
                rows: aggregate_rows,
            })
        }
        SelectProjection::GroupedAvg {
            group_column,
            avg_column,
        } => {
            let Some(group_by) = &select.group_by else {
                return Err(ErrorField {
                    code: "0A000",
                    message: "grouped AVG requires GROUP BY",
                    position: None,
                });
            };
            if group_by != group_column {
                return Err(ErrorField {
                    code: "0A000",
                    message: "GROUP BY column must match grouped AVG projection",
                    position: None,
                });
            }
            let group_idx = column_index(table, group_column)?;
            let avg_idx = int4_column_index_for_aggregate(table, avg_column, "AVG")?;
            let mut averages: BTreeMap<SqlValue, (i128, usize)> = BTreeMap::new();
            for row in rows {
                let value = int4_value_for_aggregate(&row[avg_idx], "AVG")?;
                let entry = averages.entry(row[group_idx].clone()).or_default();
                entry.0 += i128::from(value);
                entry.1 += 1;
            }
            let mut grouped = averages.into_iter().collect::<Vec<_>>();
            grouped = grouped
                .into_iter()
                .filter_map(|(group_value, (sum, count))| {
                    // HAVING evaluates the AVG against a numeric literal; both must be Decimal128.
                    // `average_text` yields a scale-16 string, so parse it back at scale 16.
                    let aggregate = SqlValue::Numeric(
                        gpu_db_protocol::Decimal128::parse_at_scale(
                            &average_text(sum, count)
                                .unwrap_or_else(|| "0.0000000000000000".to_string()),
                            16,
                        )
                        .unwrap_or(gpu_db_protocol::Decimal128::ZERO),
                    );
                    match grouped_row_matches_having(
                        select,
                        group_column,
                        &group_value,
                        "avg",
                        &aggregate,
                    ) {
                        Ok(true) => Some(Ok((group_value, (sum, count)))),
                        Ok(false) => None,
                        Err(error) => Some(Err(error)),
                    }
                })
                .collect::<Result<Vec<_>, _>>()?;
            if let Some(order) = select.order_by.first() {
                if order.column == *group_column {
                    grouped.sort_by(|(left, _), (right, _)| compare_sql_values(left, right));
                } else if order.column.eq_ignore_ascii_case("avg") {
                    grouped.sort_by(
                        |(left_value, (left_sum, left_count)),
                         (right_value, (right_sum, right_count))| {
                            compare_averages(*left_sum, *left_count, *right_sum, *right_count)
                                .then_with(|| compare_sql_values(left_value, right_value))
                        },
                    );
                } else {
                    return Err(ErrorField {
                        code: "0A000",
                        message: "GROUP BY ORDER BY must reference grouped column or avg",
                        position: None,
                    });
                }
                if order.descending {
                    grouped.reverse();
                }
            }
            if let Some(offset) = select.offset {
                grouped = grouped.into_iter().skip(offset).collect();
            }
            if let Some(limit) = select.limit {
                grouped.truncate(limit);
            }
            let columns = vec![
                aggregate_result_column(table, group_idx, group_column),
                numeric_column("avg"),
            ];
            let rows = grouped
                .into_iter()
                .map(|(value, (sum, count))| {
                    vec![Some(format_sql_value(&value)), average_text(sum, count)]
                })
                .collect();
            Ok(SelectResult { columns, rows })
        }
        SelectProjection::Min { column } | SelectProjection::Max { column } => {
            let aggregate_name = match &select.projection {
                SelectProjection::Min { .. } => "min",
                SelectProjection::Max { .. } => "max",
                _ => unreachable!(),
            };
            if select.group_by.is_some() {
                return Err(ErrorField {
                    code: "0A000",
                    message: "GROUP BY requires grouped MIN/MAX projection",
                    position: None,
                });
            }
            if let Some(order) = select.order_by.first() {
                if !order.column.eq_ignore_ascii_case(aggregate_name) {
                    return Err(ErrorField {
                        code: "0A000",
                        message: "MIN/MAX ORDER BY only supports the aggregate result",
                        position: None,
                    });
                }
            }
            let value_idx = column_index(table, column)?;
            let value = if matches!(select.projection, SelectProjection::Min { .. }) {
                rows.iter()
                    .map(|row| row[value_idx].clone())
                    .min_by(compare_sql_values)
            } else {
                rows.iter()
                    .map(|row| row[value_idx].clone())
                    .max_by(compare_sql_values)
            };
            let mut aggregate_rows = vec![vec![value.as_ref().map(format_sql_value)]];
            if let Some(offset) = select.offset {
                aggregate_rows = aggregate_rows.into_iter().skip(offset).collect();
            }
            if let Some(limit) = select.limit {
                aggregate_rows.truncate(limit);
            }
            Ok(SelectResult {
                columns: vec![aggregate_result_column(table, value_idx, aggregate_name)],
                rows: aggregate_rows,
            })
        }
        SelectProjection::GroupedMin {
            group_column,
            min_column,
        }
        | SelectProjection::GroupedMax {
            group_column,
            max_column: min_column,
        } => {
            let aggregate_name = match &select.projection {
                SelectProjection::GroupedMin { .. } => "min",
                SelectProjection::GroupedMax { .. } => "max",
                _ => unreachable!(),
            };
            let Some(group_by) = &select.group_by else {
                return Err(ErrorField {
                    code: "0A000",
                    message: "grouped MIN/MAX requires GROUP BY",
                    position: None,
                });
            };
            if group_by != group_column {
                return Err(ErrorField {
                    code: "0A000",
                    message: "GROUP BY column must match grouped MIN/MAX projection",
                    position: None,
                });
            }
            let group_idx = column_index(table, group_column)?;
            let value_idx = column_index(table, min_column)?;
            let mut extrema: BTreeMap<SqlValue, SqlValue> = BTreeMap::new();
            let choose_min = matches!(select.projection, SelectProjection::GroupedMin { .. });
            for row in rows {
                extrema
                    .entry(row[group_idx].clone())
                    .and_modify(|current| {
                        let ordering = compare_sql_values(&row[value_idx], current);
                        if (choose_min && ordering.is_lt()) || (!choose_min && ordering.is_gt()) {
                            *current = row[value_idx].clone();
                        }
                    })
                    .or_insert_with(|| row[value_idx].clone());
            }
            let mut grouped = extrema.into_iter().collect::<Vec<_>>();
            grouped = grouped
                .into_iter()
                .filter_map(|(group_value, extreme)| {
                    match grouped_row_matches_having(
                        select,
                        group_column,
                        &group_value,
                        aggregate_name,
                        &extreme,
                    ) {
                        Ok(true) => Some(Ok((group_value, extreme))),
                        Ok(false) => None,
                        Err(error) => Some(Err(error)),
                    }
                })
                .collect::<Result<Vec<_>, _>>()?;
            if let Some(order) = select.order_by.first() {
                if order.column == *group_column {
                    grouped.sort_by(|(left, _), (right, _)| compare_sql_values(left, right));
                } else if order.column.eq_ignore_ascii_case(aggregate_name) {
                    grouped.sort_by(|(left_value, left_extreme), (right_value, right_extreme)| {
                        compare_sql_values(left_extreme, right_extreme)
                            .then_with(|| compare_sql_values(left_value, right_value))
                    });
                } else {
                    return Err(ErrorField {
                        code: "0A000",
                        message: "GROUP BY ORDER BY must reference grouped column or min/max",
                        position: None,
                    });
                }
                if order.descending {
                    grouped.reverse();
                }
            }
            if let Some(offset) = select.offset {
                grouped = grouped.into_iter().skip(offset).collect();
            }
            if let Some(limit) = select.limit {
                grouped.truncate(limit);
            }
            let columns = vec![
                aggregate_result_column(table, group_idx, group_column),
                aggregate_result_column(table, value_idx, aggregate_name),
            ];
            let rows = grouped
                .into_iter()
                .map(|(value, extreme)| {
                    vec![
                        Some(format_sql_value(&value)),
                        Some(format_sql_value(&extreme)),
                    ]
                })
                .collect();
            Ok(SelectResult { columns, rows })
        }
        SelectProjection::All | SelectProjection::Columns(_) => unreachable!(),
    }
}

fn column_index(table: &Table, column: &str) -> Result<usize, ErrorField> {
    table
        .columns
        .iter()
        .position(|candidate| candidate.def.name == column)
        .ok_or(ErrorField {
            code: "42703",
            message: "column does not exist",
            position: None,
        })
}

fn aggregate_result_column(table: &Table, idx: usize, name: &str) -> Column {
    column_for_sql_type(table.columns[idx].def.ty, name)
}

fn int4_column_index(table: &Table, column: &str) -> Result<usize, ErrorField> {
    int4_column_index_for_aggregate(table, column, "SUM")
}

fn int4_column_index_for_aggregate(
    table: &Table,
    column: &str,
    aggregate: &'static str,
) -> Result<usize, ErrorField> {
    let Some(idx) = table
        .columns
        .iter()
        .position(|candidate| candidate.def.name == column)
    else {
        return Err(ErrorField {
            code: "42703",
            message: "column does not exist",
            position: None,
        });
    };
    if !matches!(table.columns[idx].def.ty, gpu_db_protocol::SqlType::Int4) {
        return Err(ErrorField {
            code: "0A000",
            message: aggregate_int4_error_message(aggregate),
            position: None,
        });
    }
    Ok(idx)
}

fn int4_value(value: &SqlValue) -> Result<i32, ErrorField> {
    int4_value_for_aggregate(value, "SUM")
}

fn int4_value_for_aggregate(value: &SqlValue, aggregate: &'static str) -> Result<i32, ErrorField> {
    match value {
        SqlValue::Int4(value) => Ok(*value),
        SqlValue::Int2(_)
        | SqlValue::Int8(_)
        | SqlValue::Numeric(_)
        | SqlValue::Bool(_)
        | SqlValue::Text(_)
        | SqlValue::Date(_)
        | SqlValue::Timestamp(_)
        | SqlValue::Uuid(_) => {
            Err(ErrorField {
                code: "0A000",
                message: aggregate_int4_error_message(aggregate),
                position: None,
            })
        }
    }
}

fn aggregate_int4_error_message(aggregate: &str) -> &'static str {
    match aggregate {
        "AVG" => "AVG only supports int4 columns",
        _ => "SUM only supports int4 columns",
    }
}

fn average_text(sum: i128, count: usize) -> Option<String> {
    if count == 0 {
        return None;
    }
    let count = count as i128;
    let negative = sum.is_negative();
    let abs_sum = sum.abs();
    let whole = abs_sum / count;
    let mut remainder = abs_sum % count;
    let mut fractional = String::with_capacity(16);
    for _ in 0..16 {
        remainder *= 10;
        fractional.push(char::from(b'0' + u8::try_from(remainder / count).unwrap()));
        remainder %= count;
    }
    Some(format!(
        "{}{}.{fractional}",
        if negative { "-" } else { "" },
        whole
    ))
}

fn compare_averages(
    left_sum: i128,
    left_count: usize,
    right_sum: i128,
    right_count: usize,
) -> std::cmp::Ordering {
    (left_sum * right_count as i128).cmp(&(right_sum * left_count as i128))
}

fn format_sql_value(value: &SqlValue) -> String {
    match value {
        SqlValue::Int2(value) => value.to_string(),
        SqlValue::Int4(value) => value.to_string(),
        SqlValue::Int8(value) => value.to_string(),
        SqlValue::Numeric(value) => value.to_decimal_string(),
        SqlValue::Bool(value) => bool_text(*value),
        SqlValue::Text(value) => value.clone(),
        SqlValue::Date(value) => gpu_db_protocol::datetime::format_date(*value),
        SqlValue::Timestamp(value) => gpu_db_protocol::datetime::format_timestamp(*value),
        SqlValue::Uuid(value) => gpu_db_protocol::uuid::format_uuid(value),
    }
}

fn parse_materialized_row_value(
    value: &str,
    ty: gpu_db_protocol::SqlType,
) -> Result<SqlValue, ErrorField> {
    match ty {
        gpu_db_protocol::SqlType::Int2 => {
            value
                .parse::<i16>()
                .map(SqlValue::Int2)
                .map_err(|_| ErrorField {
                    code: "22P02",
                    message: "invalid input syntax for type smallint",
                    position: None,
                })
        }
        gpu_db_protocol::SqlType::Int4 => {
            value
                .parse::<i32>()
                .map(SqlValue::Int4)
                .map_err(|_| ErrorField {
                    code: "22P02",
                    message: "invalid input syntax for type integer",
                    position: None,
                })
        }
        gpu_db_protocol::SqlType::Int8 => {
            value
                .parse::<i64>()
                .map(SqlValue::Int8)
                .map_err(|_| ErrorField {
                    code: "22P02",
                    message: "invalid input syntax for type bigint",
                    position: None,
                })
        }
        gpu_db_protocol::SqlType::Numeric { scale, .. } => {
            gpu_db_protocol::Decimal128::parse_at_scale(value, scale)
                .map(SqlValue::Numeric)
                .ok_or(ErrorField {
                    code: "22P02",
                    message: "invalid input syntax for type numeric",
                    position: None,
                })
        }
        gpu_db_protocol::SqlType::Bool => match value.to_ascii_lowercase().as_str() {
            "t" | "true" => Ok(SqlValue::Bool(true)),
            "f" | "false" => Ok(SqlValue::Bool(false)),
            _ => Err(ErrorField {
                code: "22P02",
                message: "invalid input syntax for type boolean",
                position: None,
            }),
        },
        gpu_db_protocol::SqlType::Text => Ok(SqlValue::Text(value.to_string())),
        gpu_db_protocol::SqlType::Date => gpu_db_protocol::datetime::parse_date(value)
            .map(SqlValue::Date)
            .ok_or(ErrorField {
                code: "22P02",
                message: "invalid input syntax for type date",
                position: None,
            }),
        gpu_db_protocol::SqlType::Timestamp => gpu_db_protocol::datetime::parse_timestamp(value)
            .map(SqlValue::Timestamp)
            .ok_or(ErrorField {
                code: "22P02",
                message: "invalid input syntax for type timestamp",
                position: None,
            }),
        gpu_db_protocol::SqlType::Uuid => gpu_db_protocol::uuid::parse_uuid(value)
            .map(SqlValue::Uuid)
            .ok_or(ErrorField {
                code: "22P02",
                message: "invalid input syntax for type uuid",
                position: None,
            }),
    }
}

fn materialize_select_rows(
    result: SelectResult,
    expected_columns: Option<&[CatalogColumn]>,
) -> Result<(Vec<CatalogColumn>, Vec<Vec<SqlValue>>), ErrorField> {
    let columns = result
        .columns
        .into_iter()
        .enumerate()
        .map(|(idx, column)| {
            Ok(CatalogColumn {
                attnum: i16::try_from(idx + 1).map_err(|_| ErrorField {
                    code: "54000",
                    message: "too many columns for bootstrap catalog",
                    position: None,
                })?,
                def: gpu_db_protocol::ColumnDef {
                    name: column.name,
                    ty: match column.oid {
                        23 => gpu_db_protocol::SqlType::Int4,
                        25 => gpu_db_protocol::SqlType::Text,
                        _ => {
                            return Err(ErrorField {
                                code: "0A000",
                                message: "materialized view column type is unsupported",
                                position: None,
                            })
                        }
                    },
                    domain: None,
                    default: None,
                },
            })
        })
        .collect::<Result<Vec<_>, _>>()?;
    if let Some(expected_columns) = expected_columns {
        if columns.len() != expected_columns.len()
            || columns
                .iter()
                .zip(expected_columns.iter())
                .any(|(left, right)| left.def.name != right.def.name || left.def.ty != right.def.ty)
        {
            return Err(ErrorField {
                code: "0A000",
                message: "materialized view refresh changed the result shape",
                position: None,
            });
        }
    }
    let column_types = columns
        .iter()
        .map(|column| column.def.ty)
        .collect::<Vec<_>>();
    let rows = result
        .rows
        .into_iter()
        .map(|row| {
            row.into_iter()
                .zip(column_types.iter().copied())
                .map(|(value, ty)| match value {
                    Some(value) => parse_materialized_row_value(&value, ty),
                    None => Err(ErrorField {
                        code: "0A000",
                        message: "NULL materialized view rows are unsupported",
                        position: None,
                    }),
                })
                .collect::<Result<Vec<_>, _>>()
        })
        .collect::<Result<Vec<_>, _>>()?;
    Ok((columns, rows))
}

fn index_definition_prefix(unique: bool) -> &'static str {
    if unique {
        "CREATE UNIQUE INDEX"
    } else {
        "CREATE INDEX"
    }
}

fn catalog_index_definition(index: &CatalogIndex) -> String {
    format!(
        "{} {} ON public.{} USING btree ({})",
        index_definition_prefix(index.unique),
        index.name,
        index.table,
        index.column
    )
}

fn unique_index_violation_error(_index_name: &str) -> ErrorField {
    ErrorField {
        code: "23505",
        message: "duplicate key value violates unique index",
        position: None,
    }
}

fn validate_unique_indexes(table: &Table, indexes: &[CatalogIndex]) -> Result<(), ErrorField> {
    for index in indexes
        .iter()
        .filter(|index| index.table == table.name && index.unique)
    {
        let Some(column_idx) = table
            .columns
            .iter()
            .position(|column| column.def.name == index.column)
        else {
            continue;
        };
        let mut seen = BTreeSet::new();
        for row in &table.rows {
            if !seen.insert(row[column_idx].clone()) {
                return Err(unique_index_violation_error(&index.name));
            }
        }
    }
    Ok(())
}

fn check_constraint_violation_error(_table: &str, _constraint: &str) -> ErrorField {
    ErrorField {
        code: "23514",
        message: "new row violates check constraint",
        position: None,
    }
}

fn validate_check_constraints(table: &Table) -> Result<(), ErrorField> {
    for constraint in &table.check_constraints {
        let Some(column_idx) = table
            .columns
            .iter()
            .position(|column| column.def.name == constraint.column)
        else {
            continue;
        };
        for row in &table.rows {
            if !select_filter_matches(&row[column_idx], constraint.op, &constraint.value) {
                return Err(check_constraint_violation_error(
                    &table.name,
                    &constraint.name,
                ));
            }
        }
    }
    Ok(())
}

fn foreign_key_violation_error() -> ErrorField {
    ErrorField {
        code: "23503",
        message: "insert or update violates foreign key constraint",
        position: None,
    }
}

fn validate_foreign_keys(session: &Session) -> Result<(), ErrorField> {
    for table in session.tables.values() {
        for foreign_key in &table.foreign_keys {
            let Some(child_column_idx) = table
                .columns
                .iter()
                .position(|column| column.def.name == foreign_key.column)
            else {
                continue;
            };
            let Some(parent) = session.tables.get(&foreign_key.referenced_table) else {
                continue;
            };
            let Some(parent_column_idx) = parent
                .columns
                .iter()
                .position(|column| column.def.name == foreign_key.referenced_column)
            else {
                continue;
            };
            let parent_values = parent
                .rows
                .iter()
                .map(|row| row[parent_column_idx].clone())
                .collect::<BTreeSet<_>>();
            for row in &table.rows {
                if !parent_values.contains(&row[child_column_idx]) {
                    return Err(foreign_key_violation_error());
                }
            }
        }
    }
    Ok(())
}

fn add_foreign_key_to_session(
    session: &mut Session,
    table_name: &str,
    constraint_name: String,
    column: String,
    referenced_table: String,
    referenced_column: String,
) -> Result<(), ErrorField> {
    if table_name == referenced_table {
        return Err(ErrorField {
            code: "0A000",
            message: "self-referential foreign keys are not supported",
            position: None,
        });
    }
    if session
        .indexes
        .iter()
        .any(|index| index.name == constraint_name)
        || session.tables.values().any(|table| {
            table
                .check_constraints
                .iter()
                .any(|constraint| constraint.name == constraint_name)
                || table
                    .foreign_keys
                    .iter()
                    .any(|constraint| constraint.name == constraint_name)
        })
        || session.tables.contains_key(&constraint_name)
        || session.views.contains_key(&constraint_name)
        || session.materialized_views.contains_key(&constraint_name)
        || session.sequences.contains_key(&constraint_name)
    {
        return Err(ErrorField {
            code: "42710",
            message: "constraint already exists",
            position: None,
        });
    }
    let Some(table) = session.tables.get(table_name) else {
        return Err(ErrorField {
            code: "42P01",
            message: "relation does not exist",
            position: None,
        });
    };
    let Some(child_column) = table
        .columns
        .iter()
        .find(|candidate| candidate.def.name == column)
    else {
        return Err(ErrorField {
            code: "42703",
            message: "column does not exist",
            position: None,
        });
    };
    let Some(parent) = session.tables.get(&referenced_table) else {
        return Err(ErrorField {
            code: "42P01",
            message: "referenced relation does not exist",
            position: None,
        });
    };
    let Some(parent_column) = parent
        .columns
        .iter()
        .find(|candidate| candidate.def.name == referenced_column)
    else {
        return Err(ErrorField {
            code: "42703",
            message: "referenced column does not exist",
            position: None,
        });
    };
    if child_column.def.ty != parent_column.def.ty {
        return Err(ErrorField {
            code: "42804",
            message: "foreign key column type does not match referenced column type",
            position: None,
        });
    }
    if !session.indexes.iter().any(|index| {
        index.table == referenced_table
            && index.column == referenced_column
            && (index.primary_key || index.unique_constraint)
    }) {
        return Err(ErrorField {
            code: "42830",
            message: "there is no unique constraint matching given keys for referenced table",
            position: None,
        });
    }
    let foreign_key = CatalogForeignKey {
        name: constraint_name,
        table: table_name.to_string(),
        column,
        referenced_table,
        referenced_column,
    };
    session
        .tables
        .get_mut(table_name)
        .expect("table existence checked")
        .foreign_keys
        .push(foreign_key);
    if let Err(error) = validate_foreign_keys(session) {
        session
            .tables
            .get_mut(table_name)
            .expect("table existence checked")
            .foreign_keys
            .pop();
        return Err(error);
    }
    session.mark_table_dirty(table_name.to_string());
    Ok(())
}

fn drop_column_from_session(
    session: &mut Session,
    table_name: &str,
    column_name: &str,
) -> Result<(), ErrorField> {
    if session.views.contains_key(table_name)
        || session.materialized_views.contains_key(table_name)
        || session.sequences.contains_key(table_name)
    {
        return Err(ErrorField {
            code: "42809",
            message: "relation is not a table",
            position: None,
        });
    }
    let referenced_by_foreign_key = session.tables.values().any(|candidate| {
        candidate.foreign_keys.iter().any(|constraint| {
            constraint.referenced_table == table_name && constraint.referenced_column == column_name
        })
    });
    let Some(table) = session.tables.get_mut(table_name) else {
        return Err(ErrorField {
            code: "42P01",
            message: "relation does not exist",
            position: None,
        });
    };
    let Some(drop_idx) = table
        .columns
        .iter()
        .position(|column| column.def.name == column_name)
    else {
        return Err(ErrorField {
            code: "42703",
            message: "column does not exist",
            position: None,
        });
    };
    if session
        .indexes
        .iter()
        .any(|index| index.table == table_name && index.column == column_name)
        || table
            .check_constraints
            .iter()
            .any(|constraint| constraint.column == column_name)
        || table
            .foreign_keys
            .iter()
            .any(|constraint| constraint.column == column_name)
        || referenced_by_foreign_key
    {
        return Err(ErrorField {
            code: "2BP01",
            message: "cannot drop column because an index or constraint depends on it",
            position: None,
        });
    }

    let dropped_attnum = table.columns[drop_idx].attnum;
    table.columns.remove(drop_idx);
    for (idx, column) in table.columns.iter_mut().enumerate() {
        column.attnum = i16::try_from(idx + 1).map_err(|_| ErrorField {
            code: "54000",
            message: "too many columns for bootstrap catalog",
            position: None,
        })?;
    }
    for row in &mut table.rows {
        row.remove(drop_idx);
    }

    let shifted_comments = session
        .comments
        .iter()
        .filter_map(|(target, comment)| match target {
            CatalogCommentTarget::Column { table, attnum }
                if table == table_name && *attnum > dropped_attnum =>
            {
                Some((
                    target.clone(),
                    CatalogCommentTarget::Column {
                        table: table.clone(),
                        attnum: *attnum - 1,
                    },
                    comment.clone(),
                ))
            }
            _ => None,
        })
        .collect::<Vec<_>>();
    let removed_targets = session
        .comments
        .keys()
        .filter(|target| match target {
            CatalogCommentTarget::Column { table, attnum } => {
                table == table_name && *attnum >= dropped_attnum
            }
            _ => false,
        })
        .cloned()
        .collect::<Vec<_>>();
    for target in removed_targets {
        session.comments.remove(&target);
        session.mark_comment_dirty(target);
    }
    for (old_target, new_target, comment) in shifted_comments {
        session.comments.remove(&old_target);
        session.comments.insert(new_target.clone(), comment);
        session.mark_comment_dirty(new_target);
    }
    session.mark_table_dirty(table_name.to_string());
    session.persist_catalog_snapshot();
    Ok(())
}

fn rename_column_in_session(
    session: &mut Session,
    table_name: &str,
    old_name: &str,
    new_name: &str,
) -> Result<(), ErrorField> {
    if session.views.contains_key(table_name)
        || session.materialized_views.contains_key(table_name)
        || session.sequences.contains_key(table_name)
    {
        return Err(ErrorField {
            code: "42809",
            message: "relation is not a table",
            position: None,
        });
    }
    let Some(table) = session.tables.get_mut(table_name) else {
        return Err(ErrorField {
            code: "42P01",
            message: "relation does not exist",
            position: None,
        });
    };
    let Some(column_idx) = table
        .columns
        .iter()
        .position(|column| column.def.name == old_name)
    else {
        return Err(ErrorField {
            code: "42703",
            message: "column does not exist",
            position: None,
        });
    };
    if table
        .columns
        .iter()
        .any(|column| column.def.name == new_name)
    {
        return Err(ErrorField {
            code: "42701",
            message: "column already exists",
            position: None,
        });
    }
    table.columns[column_idx].def.name = new_name.to_string();
    for index in &mut session.indexes {
        if index.table == table_name && index.column == old_name {
            index.column = new_name.to_string();
            session.dirty_indexes = true;
        }
    }
    for constraint in &mut table.check_constraints {
        if constraint.column == old_name {
            constraint.column = new_name.to_string();
        }
    }
    for constraint in &mut table.foreign_keys {
        if constraint.column == old_name {
            constraint.column = new_name.to_string();
        }
        if constraint.referenced_table == table_name && constraint.referenced_column == old_name {
            constraint.referenced_column = new_name.to_string();
        }
    }
    session.mark_table_dirty(table_name.to_string());
    session.persist_catalog_snapshot();
    Ok(())
}

fn rename_constraint_in_session(
    session: &mut Session,
    table_name: &str,
    old_name: &str,
    new_name: &str,
    table_if_exists: bool,
) -> Result<(), ErrorField> {
    if session.views.contains_key(table_name)
        || session.materialized_views.contains_key(table_name)
        || session.sequences.contains_key(table_name)
    {
        return Err(ErrorField {
            code: "42809",
            message: "relation is not a table",
            position: None,
        });
    }
    if !session.tables.contains_key(table_name) {
        if table_if_exists {
            return Ok(());
        }
        return Err(ErrorField {
            code: "42P01",
            message: "relation does not exist",
            position: None,
        });
    }
    if session.indexes.iter().any(|index| index.name == new_name)
        || session.tables.values().any(|table| {
            table
                .check_constraints
                .iter()
                .any(|constraint| constraint.name == new_name)
                || table
                    .foreign_keys
                    .iter()
                    .any(|constraint| constraint.name == new_name)
        })
        || session.tables.contains_key(new_name)
        || session.views.contains_key(new_name)
        || session.materialized_views.contains_key(new_name)
        || session.sequences.contains_key(new_name)
    {
        return Err(ErrorField {
            code: "42P07",
            message: "relation already exists",
            position: None,
        });
    }
    if let Some(index) = session.indexes.iter_mut().find(|index| {
        index.table == table_name
            && index.name == old_name
            && (index.primary_key || index.unique_constraint)
    }) {
        index.name = new_name.to_string();
        session.dirty_indexes = true;
    } else if let Some(table) = session.tables.get_mut(table_name) {
        if let Some(check) = table
            .check_constraints
            .iter_mut()
            .find(|constraint| constraint.name == old_name)
        {
            check.name = new_name.to_string();
            session.mark_table_dirty(table_name.to_string());
        } else if let Some(foreign_key) = table
            .foreign_keys
            .iter_mut()
            .find(|constraint| constraint.name == old_name)
        {
            foreign_key.name = new_name.to_string();
            session.mark_table_dirty(table_name.to_string());
        } else {
            return Err(ErrorField {
                code: "42704",
                message: "constraint does not exist",
                position: None,
            });
        }
    } else {
        return Err(ErrorField {
            code: "42704",
            message: "constraint does not exist",
            position: None,
        });
    }

    let old_index_target = CatalogCommentTarget::Index {
        index: old_name.to_string(),
    };
    if let Some(comment) = session.comments.remove(&old_index_target) {
        let new_index_target = CatalogCommentTarget::Index {
            index: new_name.to_string(),
        };
        session.comments.insert(new_index_target.clone(), comment);
        session.mark_comment_dirty(old_index_target);
        session.mark_comment_dirty(new_index_target);
    }
    let old_constraint_target = CatalogCommentTarget::Constraint {
        table: table_name.to_string(),
        constraint: old_name.to_string(),
    };
    if let Some(comment) = session.comments.remove(&old_constraint_target) {
        let new_constraint_target = CatalogCommentTarget::Constraint {
            table: table_name.to_string(),
            constraint: new_name.to_string(),
        };
        session
            .comments
            .insert(new_constraint_target.clone(), comment);
        session.mark_comment_dirty(old_constraint_target);
        session.mark_comment_dirty(new_constraint_target);
    }

    session.persist_catalog_snapshot();
    Ok(())
}

fn rename_index_in_session(
    session: &mut Session,
    old_name: &str,
    new_name: &str,
) -> Result<(), ErrorField> {
    if session.indexes.iter().any(|index| index.name == new_name)
        || session.tables.contains_key(new_name)
        || session.views.contains_key(new_name)
        || session.materialized_views.contains_key(new_name)
        || session.sequences.contains_key(new_name)
    {
        return Err(ErrorField {
            code: "42P07",
            message: "relation already exists",
            position: None,
        });
    }
    let Some(index) = session
        .indexes
        .iter_mut()
        .find(|index| index.name == old_name)
    else {
        return Err(ErrorField {
            code: "42704",
            message: "index does not exist",
            position: None,
        });
    };
    if index.primary_key || index.unique_constraint {
        return Err(ErrorField {
            code: "0A000",
            message: "cannot rename constraint-backed index with ALTER INDEX",
            position: None,
        });
    }
    let table_name = index.table.clone();
    index.name = new_name.to_string();
    session.dirty_indexes = true;
    session.mark_table_dirty(table_name);

    let old_target = CatalogCommentTarget::Index {
        index: old_name.to_string(),
    };
    if let Some(comment) = session.comments.remove(&old_target) {
        let new_target = CatalogCommentTarget::Index {
            index: new_name.to_string(),
        };
        session.comments.insert(new_target.clone(), comment);
        session.mark_comment_dirty(old_target);
        session.mark_comment_dirty(new_target);
    }

    session.persist_catalog_snapshot();
    Ok(())
}

fn rename_sequence_in_session(
    session: &mut Session,
    old_name: &str,
    new_name: &str,
) -> Result<(), ErrorField> {
    if session.tables.contains_key(old_name)
        || session.views.contains_key(old_name)
        || session.materialized_views.contains_key(old_name)
    {
        return Err(ErrorField {
            code: "42809",
            message: "relation is not a sequence",
            position: None,
        });
    }
    if !session.sequences.contains_key(old_name) {
        return Err(ErrorField {
            code: "42P01",
            message: "sequence does not exist",
            position: None,
        });
    }
    if session.tables.contains_key(new_name)
        || session.views.contains_key(new_name)
        || session.materialized_views.contains_key(new_name)
        || session.sequences.contains_key(new_name)
    {
        return Err(ErrorField {
            code: "42P07",
            message: "relation already exists",
            position: None,
        });
    }
    let mut sequence = session
        .sequences
        .remove(old_name)
        .expect("sequence existence validated");
    sequence.name = new_name.to_string();
    session.sequences.insert(new_name.to_string(), sequence);
    if let Some(value) = session.currval_sequences.remove(old_name) {
        session
            .currval_sequences
            .insert(new_name.to_string(), value);
    }
    if let Some(acl) = session.table_acls.remove(old_name) {
        session.table_acls.insert(new_name.to_string(), acl);
        session.mark_table_acl_dirty(old_name.to_string());
        session.mark_table_acl_dirty(new_name.to_string());
    }
    session.mark_sequence_dirty(old_name.to_string());
    session.mark_sequence_dirty(new_name.to_string());

    let old_target = CatalogCommentTarget::Sequence {
        sequence: old_name.to_string(),
    };
    if let Some(comment) = session.comments.remove(&old_target) {
        let new_target = CatalogCommentTarget::Sequence {
            sequence: new_name.to_string(),
        };
        session.comments.insert(new_target.clone(), comment);
        session.mark_comment_dirty(old_target);
        session.mark_comment_dirty(new_target);
    }

    session.persist_catalog_snapshot();
    Ok(())
}

fn rename_function_in_session(
    session: &mut Session,
    old_name: &str,
    new_name: &str,
) -> Result<(), ErrorField> {
    if !session.functions.contains_key(old_name) {
        return Err(ErrorField {
            code: "42883",
            message: "function does not exist",
            position: None,
        });
    }
    if session.functions.contains_key(new_name) {
        return Err(ErrorField {
            code: "42723",
            message: "function already exists with same argument types",
            position: None,
        });
    }
    let mut function = session
        .functions
        .remove(old_name)
        .expect("function existence validated");
    function.name = new_name.to_string();
    session.functions.insert(new_name.to_string(), function);
    session.mark_function_dirty(old_name.to_string());
    session.mark_function_dirty(new_name.to_string());

    let old_target = CatalogCommentTarget::Function {
        function: old_name.to_string(),
    };
    if let Some(comment) = session.comments.remove(&old_target) {
        let new_target = CatalogCommentTarget::Function {
            function: new_name.to_string(),
        };
        session.comments.insert(new_target.clone(), comment);
        session.mark_comment_dirty(old_target);
        session.mark_comment_dirty(new_target);
    }

    session.persist_catalog_snapshot();
    Ok(())
}

fn rename_table_in_session(
    session: &mut Session,
    old_name: &str,
    new_name: &str,
    if_exists: bool,
) -> Result<(), ErrorField> {
    if session.views.contains_key(old_name)
        || session.materialized_views.contains_key(old_name)
        || session.sequences.contains_key(old_name)
    {
        return Err(ErrorField {
            code: "42809",
            message: "relation is not a table",
            position: None,
        });
    }
    if !session.tables.contains_key(old_name) {
        if if_exists {
            return Ok(());
        }
        return Err(ErrorField {
            code: "42P01",
            message: "relation does not exist",
            position: None,
        });
    }
    if session.tables.contains_key(new_name)
        || session.views.contains_key(new_name)
        || session.materialized_views.contains_key(new_name)
        || session.sequences.contains_key(new_name)
    {
        return Err(ErrorField {
            code: "42P07",
            message: "relation already exists",
            position: None,
        });
    }
    if session
        .views
        .values()
        .any(|view| view.query.table == old_name)
    {
        return Err(ErrorField {
            code: "2BP01",
            message: "cannot rename relation because a view depends on it",
            position: None,
        });
    }
    let Some(mut table) = session.tables.remove(old_name) else {
        return Ok(());
    };
    table.name = new_name.to_string();
    session.tables.insert(new_name.to_string(), table);
    if let Some(acl) = session.table_acls.remove(old_name) {
        session.table_acls.insert(new_name.to_string(), acl);
        session.mark_table_acl_dirty(old_name.to_string());
        session.mark_table_acl_dirty(new_name.to_string());
    }
    for index in &mut session.indexes {
        if index.table == old_name {
            index.table = new_name.to_string();
            session.dirty_indexes = true;
        }
    }
    let mut dirty_fk_tables = Vec::new();
    for table in session.tables.values_mut() {
        let mut changed = false;
        for foreign_key in &mut table.foreign_keys {
            if foreign_key.table == old_name {
                foreign_key.table = new_name.to_string();
                changed = true;
            }
            if foreign_key.referenced_table == old_name {
                foreign_key.referenced_table = new_name.to_string();
                changed = true;
            }
        }
        if changed {
            dirty_fk_tables.push(table.name.clone());
        }
    }
    for table in dirty_fk_tables {
        session.mark_table_dirty(table);
    }

    let mut retargeted_comments = Vec::new();
    let old_targets = session
        .comments
        .iter()
        .filter_map(|(target, comment)| match target {
            CatalogCommentTarget::Table { table } if table == old_name => Some((
                target.clone(),
                CatalogCommentTarget::Table {
                    table: new_name.to_string(),
                },
                comment.clone(),
            )),
            CatalogCommentTarget::Column { table, attnum } if table == old_name => Some((
                target.clone(),
                CatalogCommentTarget::Column {
                    table: new_name.to_string(),
                    attnum: *attnum,
                },
                comment.clone(),
            )),
            CatalogCommentTarget::Constraint { table, constraint } if table == old_name => Some((
                target.clone(),
                CatalogCommentTarget::Constraint {
                    table: new_name.to_string(),
                    constraint: constraint.clone(),
                },
                comment.clone(),
            )),
            _ => None,
        })
        .collect::<Vec<_>>();
    for (old_target, new_target, comment) in old_targets {
        session.comments.remove(&old_target);
        retargeted_comments.push((old_target, new_target, comment));
    }
    for (old_target, new_target, comment) in retargeted_comments {
        session.comments.insert(new_target.clone(), comment);
        session.mark_comment_dirty(old_target);
        session.mark_comment_dirty(new_target);
    }

    session.mark_table_dirty(old_name.to_string());
    session.mark_table_dirty(new_name.to_string());
    session.persist_catalog_snapshot();
    Ok(())
}

fn shared_catalog_contains_table(table: &str) -> bool {
    shared_catalog()
        .lock()
        .expect("shared catalog mutex poisoned")
        .tables
        .contains_key(table)
}

fn shared_catalog_contains_view(view: &str) -> bool {
    shared_catalog()
        .lock()
        .expect("shared catalog mutex poisoned")
        .views
        .contains_key(view)
}

fn shared_catalog_contains_sequence(sequence: &str) -> bool {
    shared_catalog()
        .lock()
        .expect("shared catalog mutex poisoned")
        .sequences
        .contains_key(sequence)
}

fn shared_catalog_contains_live_index(index: &str) -> bool {
    let catalog = shared_catalog()
        .lock()
        .expect("shared catalog mutex poisoned");
    catalog
        .indexes
        .iter()
        .any(|candidate| candidate.name == index && catalog.tables.contains_key(&candidate.table))
}

fn shared_catalog_contains_table_constraint(table: &str, constraint: &str) -> bool {
    let catalog = shared_catalog()
        .lock()
        .expect("shared catalog mutex poisoned");
    (catalog.tables.contains_key(table)
        && catalog.indexes.iter().any(|candidate| {
            candidate.table == table
                && candidate.name == constraint
                && (candidate.primary_key || candidate.unique_constraint)
        }))
        || catalog.tables.get(table).is_some_and(|table| {
            table
                .check_constraints
                .iter()
                .any(|candidate| candidate.name == constraint)
        })
}

fn add_primary_key_to_session(
    session: &mut Session,
    table_name: &str,
    constraint_name: String,
    column: String,
) -> Result<(), ErrorField> {
    if session
        .indexes
        .iter()
        .any(|index| index.name == constraint_name)
        || session.tables.contains_key(&constraint_name)
        || session.views.contains_key(&constraint_name)
        || session.materialized_views.contains_key(&constraint_name)
        || session.sequences.contains_key(&constraint_name)
    {
        return Err(ErrorField {
            code: "42P07",
            message: "relation already exists",
            position: None,
        });
    }
    if session
        .indexes
        .iter()
        .any(|index| index.table == table_name && index.primary_key)
    {
        return Err(ErrorField {
            code: "42P16",
            message: "multiple primary keys are not allowed",
            position: None,
        });
    }
    let Some(table) = session.tables.get(table_name) else {
        return Err(ErrorField {
            code: "42P01",
            message: "relation does not exist",
            position: None,
        });
    };
    if !table
        .columns
        .iter()
        .any(|candidate| candidate.def.name == column)
    {
        return Err(ErrorField {
            code: "42703",
            message: "column does not exist",
            position: None,
        });
    }
    let mut candidate_indexes = session.indexes.clone();
    candidate_indexes.push(CatalogIndex {
        name: constraint_name.clone(),
        table: table_name.to_string(),
        column: column.clone(),
        unique: true,
        primary_key: true,
        unique_constraint: false,
    });
    validate_unique_indexes(table, &candidate_indexes)?;
    session.indexes.push(CatalogIndex {
        name: constraint_name,
        table: table_name.to_string(),
        column,
        unique: true,
        primary_key: true,
        unique_constraint: false,
    });
    session.dirty_indexes = true;
    Ok(())
}

fn add_unique_constraint_to_session(
    session: &mut Session,
    table_name: &str,
    constraint_name: String,
    column: String,
) -> Result<(), ErrorField> {
    if session
        .indexes
        .iter()
        .any(|index| index.name == constraint_name)
        || session.tables.contains_key(&constraint_name)
        || session.views.contains_key(&constraint_name)
        || session.materialized_views.contains_key(&constraint_name)
        || session.sequences.contains_key(&constraint_name)
    {
        return Err(ErrorField {
            code: "42P07",
            message: "relation already exists",
            position: None,
        });
    }
    let Some(table) = session.tables.get(table_name) else {
        return Err(ErrorField {
            code: "42P01",
            message: "relation does not exist",
            position: None,
        });
    };
    if !table
        .columns
        .iter()
        .any(|candidate| candidate.def.name == column)
    {
        return Err(ErrorField {
            code: "42703",
            message: "column does not exist",
            position: None,
        });
    }
    let mut candidate_indexes = session.indexes.clone();
    candidate_indexes.push(CatalogIndex {
        name: constraint_name.clone(),
        table: table_name.to_string(),
        column: column.clone(),
        unique: true,
        primary_key: false,
        unique_constraint: true,
    });
    validate_unique_indexes(table, &candidate_indexes)?;
    session.indexes.push(CatalogIndex {
        name: constraint_name,
        table: table_name.to_string(),
        column,
        unique: true,
        primary_key: false,
        unique_constraint: true,
    });
    session.dirty_indexes = true;
    Ok(())
}

fn format_default_expr(value: &SqlValue) -> String {
    match value {
        SqlValue::Int2(value) => format!("{value}::smallint"),
        SqlValue::Int4(value) => value.to_string(),
        SqlValue::Text(value) => format!("'{}'::text", value.replace('\'', "''")),
        SqlValue::Int8(value) => value.to_string(),
        SqlValue::Numeric(value) => value.to_decimal_string(),
        SqlValue::Bool(value) => bool_text(*value),
        SqlValue::Date(value) => {
            format!("'{}'::date", gpu_db_protocol::datetime::format_date(*value))
        }
        SqlValue::Timestamp(value) => format!(
            "'{}'::timestamp",
            gpu_db_protocol::datetime::format_timestamp(*value)
        ),
        SqlValue::Uuid(value) => format!("'{}'::uuid", gpu_db_protocol::uuid::format_uuid(value)),
    }
}

fn format_column_default_expr(value: &ColumnDefault) -> String {
    match value {
        ColumnDefault::Literal(value) => format_default_expr(value),
        ColumnDefault::SequenceNextVal { sequence, .. } => {
            format!("nextval('{}'::regclass)", sequence.replace('\'', "''"))
        }
    }
}

struct Session {
    in_transaction: bool,
    prepared: HashMap<String, PreparedStatement>,
    portals: HashMap<String, Portal>,
    cursors: HashMap<String, Cursor>,
    tables: HashMap<String, Table>,
    views: HashMap<String, View>,
    materialized_views: HashMap<String, MaterializedView>,
    functions: BTreeMap<String, FunctionInfo>,
    sequences: HashMap<String, Sequence>,
    domains: BTreeMap<String, Domain>,
    publications: BTreeMap<String, Publication>,
    subscriptions: BTreeMap<String, Subscription>,
    roles: BTreeMap<String, RoleInfo>,
    databases: BTreeMap<String, DatabaseInfo>,
    tablespaces: BTreeMap<String, TablespaceInfo>,
    current_role: Option<String>,
    public_schema_exists: bool,
    public_schema_implicit: bool,
    currval_sequences: HashMap<String, i64>,
    indexes: Vec<CatalogIndex>,
    table_acls: BTreeMap<String, BTreeMap<String, BTreeSet<TablePrivilege>>>,
    database_acls: BTreeMap<String, BTreeMap<String, BTreeSet<DatabasePrivilege>>>,
    tablespace_acls: BTreeMap<String, BTreeMap<String, BTreeSet<TablespacePrivilege>>>,
    schema_acl: BTreeMap<String, BTreeSet<SchemaPrivilege>>,
    default_table_acl: BTreeMap<String, BTreeSet<TablePrivilege>>,
    comments: BTreeMap<CatalogCommentTarget, String>,
    dirty_tables: BTreeSet<String>,
    dirty_views: BTreeSet<String>,
    dirty_materialized_views: BTreeSet<String>,
    dirty_functions: BTreeSet<String>,
    dirty_sequences: BTreeSet<String>,
    dirty_domains: BTreeSet<String>,
    dirty_publications: BTreeSet<String>,
    dirty_subscriptions: BTreeSet<String>,
    dirty_roles: BTreeSet<String>,
    dirty_databases: BTreeSet<String>,
    dirty_tablespaces: BTreeSet<String>,
    dirty_schema: bool,
    dirty_indexes: bool,
    dirty_table_acls: BTreeSet<String>,
    dirty_database_acls: BTreeSet<String>,
    dirty_tablespace_acls: BTreeSet<String>,
    dirty_schema_acl: bool,
    dirty_default_table_acl: bool,
    dirty_comment_targets: BTreeSet<CatalogCommentTarget>,
    copy_in: Option<CopyInState>,
    next_relation_oid: u32,
    shared_catalog: bool,
}

#[derive(Clone, Debug)]
struct SharedCatalog {
    tables: HashMap<String, Table>,
    views: HashMap<String, View>,
    materialized_views: HashMap<String, MaterializedView>,
    functions: BTreeMap<String, FunctionInfo>,
    sequences: HashMap<String, Sequence>,
    domains: BTreeMap<String, Domain>,
    publications: BTreeMap<String, Publication>,
    subscriptions: BTreeMap<String, Subscription>,
    roles: BTreeMap<String, RoleInfo>,
    databases: BTreeMap<String, DatabaseInfo>,
    tablespaces: BTreeMap<String, TablespaceInfo>,
    public_schema_exists: bool,
    public_schema_implicit: bool,
    indexes: Vec<CatalogIndex>,
    table_acls: BTreeMap<String, BTreeMap<String, BTreeSet<TablePrivilege>>>,
    database_acls: BTreeMap<String, BTreeMap<String, BTreeSet<DatabasePrivilege>>>,
    tablespace_acls: BTreeMap<String, BTreeMap<String, BTreeSet<TablespacePrivilege>>>,
    schema_acl: BTreeMap<String, BTreeSet<SchemaPrivilege>>,
    default_table_acl: BTreeMap<String, BTreeSet<TablePrivilege>>,
    comments: BTreeMap<CatalogCommentTarget, String>,
    next_relation_oid: u32,
}

impl Default for SharedCatalog {
    fn default() -> Self {
        Self {
            tables: HashMap::new(),
            views: HashMap::new(),
            materialized_views: HashMap::new(),
            functions: BTreeMap::new(),
            sequences: HashMap::new(),
            domains: BTreeMap::new(),
            publications: BTreeMap::new(),
            subscriptions: BTreeMap::new(),
            roles: BTreeMap::new(),
            databases: BTreeMap::new(),
            tablespaces: BTreeMap::new(),
            public_schema_exists: true,
            public_schema_implicit: true,
            indexes: Vec::new(),
            table_acls: BTreeMap::new(),
            database_acls: BTreeMap::new(),
            tablespace_acls: BTreeMap::new(),
            schema_acl: BTreeMap::new(),
            default_table_acl: BTreeMap::new(),
            comments: BTreeMap::new(),
            next_relation_oid: FIRST_USER_RELATION_OID,
        }
    }
}

fn shared_catalog() -> &'static Mutex<SharedCatalog> {
    SHARED_CATALOG.get_or_init(|| Mutex::new(SharedCatalog::default()))
}

impl Default for Session {
    fn default() -> Self {
        Self::new(false)
    }
}

impl Session {
    fn new(shared_catalog_enabled: bool) -> Self {
        let catalog = if shared_catalog_enabled {
            shared_catalog()
                .lock()
                .expect("shared catalog mutex poisoned")
                .clone()
        } else {
            SharedCatalog::default()
        };
        Self {
            in_transaction: false,
            prepared: HashMap::new(),
            portals: HashMap::new(),
            cursors: HashMap::new(),
            tables: catalog.tables,
            views: catalog.views,
            materialized_views: catalog.materialized_views,
            functions: catalog.functions,
            sequences: catalog.sequences,
            domains: catalog.domains,
            publications: catalog.publications,
            subscriptions: catalog.subscriptions,
            roles: catalog.roles,
            databases: catalog.databases,
            tablespaces: catalog.tablespaces,
            current_role: None,
            public_schema_exists: catalog.public_schema_exists,
            public_schema_implicit: catalog.public_schema_implicit,
            currval_sequences: HashMap::new(),
            indexes: catalog.indexes,
            table_acls: catalog.table_acls,
            database_acls: catalog.database_acls,
            tablespace_acls: catalog.tablespace_acls,
            schema_acl: catalog.schema_acl,
            default_table_acl: catalog.default_table_acl,
            comments: catalog.comments,
            dirty_tables: BTreeSet::new(),
            dirty_views: BTreeSet::new(),
            dirty_materialized_views: BTreeSet::new(),
            dirty_functions: BTreeSet::new(),
            dirty_sequences: BTreeSet::new(),
            dirty_domains: BTreeSet::new(),
            dirty_publications: BTreeSet::new(),
            dirty_subscriptions: BTreeSet::new(),
            dirty_roles: BTreeSet::new(),
            dirty_databases: BTreeSet::new(),
            dirty_tablespaces: BTreeSet::new(),
            dirty_schema: false,
            dirty_indexes: false,
            dirty_table_acls: BTreeSet::new(),
            dirty_database_acls: BTreeSet::new(),
            dirty_tablespace_acls: BTreeSet::new(),
            dirty_schema_acl: false,
            dirty_default_table_acl: false,
            dirty_comment_targets: BTreeSet::new(),
            copy_in: None,
            next_relation_oid: catalog.next_relation_oid,
            shared_catalog: shared_catalog_enabled,
        }
    }

    fn mark_table_dirty(&mut self, table: impl Into<String>) {
        self.dirty_tables.insert(table.into());
    }

    fn mark_view_dirty(&mut self, view: impl Into<String>) {
        self.dirty_views.insert(view.into());
    }

    fn mark_materialized_view_dirty(&mut self, view: impl Into<String>) {
        self.dirty_materialized_views.insert(view.into());
    }

    fn mark_function_dirty(&mut self, function: impl Into<String>) {
        self.dirty_functions.insert(function.into());
    }

    fn mark_sequence_dirty(&mut self, sequence: impl Into<String>) {
        self.dirty_sequences.insert(sequence.into());
    }

    fn mark_domain_dirty(&mut self, domain: impl Into<String>) {
        self.dirty_domains.insert(domain.into());
    }

    fn mark_publication_dirty(&mut self, publication: impl Into<String>) {
        self.dirty_publications.insert(publication.into());
    }

    fn mark_subscription_dirty(&mut self, subscription: impl Into<String>) {
        self.dirty_subscriptions.insert(subscription.into());
    }

    fn mark_role_dirty(&mut self, role: impl Into<String>) {
        self.dirty_roles.insert(role.into());
    }

    fn mark_database_dirty(&mut self, database: impl Into<String>) {
        self.dirty_databases.insert(database.into());
    }

    fn mark_tablespace_dirty(&mut self, tablespace: impl Into<String>) {
        self.dirty_tablespaces.insert(tablespace.into());
    }

    fn mark_schema_dirty(&mut self) {
        self.dirty_schema = true;
    }

    fn mark_table_acl_dirty(&mut self, table: impl Into<String>) {
        self.dirty_table_acls.insert(table.into());
    }

    fn mark_database_acl_dirty(&mut self, database: impl Into<String>) {
        self.dirty_database_acls.insert(database.into());
    }

    fn mark_tablespace_acl_dirty(&mut self, tablespace: impl Into<String>) {
        self.dirty_tablespace_acls.insert(tablespace.into());
    }

    fn mark_schema_acl_dirty(&mut self) {
        self.dirty_schema_acl = true;
    }

    fn mark_default_table_acl_dirty(&mut self) {
        self.dirty_default_table_acl = true;
    }

    fn mark_comment_dirty(&mut self, target: CatalogCommentTarget) {
        self.dirty_comment_targets.insert(target);
    }

    fn persist_catalog_snapshot(&mut self) {
        if !self.shared_catalog {
            self.dirty_tables.clear();
            self.dirty_views.clear();
            self.dirty_materialized_views.clear();
            self.dirty_functions.clear();
            self.dirty_sequences.clear();
            self.dirty_domains.clear();
            self.dirty_publications.clear();
            self.dirty_subscriptions.clear();
            self.dirty_roles.clear();
            self.dirty_databases.clear();
            self.dirty_tablespaces.clear();
            self.dirty_schema = false;
            self.dirty_table_acls.clear();
            self.dirty_database_acls.clear();
            self.dirty_tablespace_acls.clear();
            self.dirty_schema_acl = false;
            self.dirty_default_table_acl = false;
            self.dirty_comment_targets.clear();
            return;
        }
        let mut catalog = shared_catalog()
            .lock()
            .expect("shared catalog mutex poisoned");
        for table_name in &self.dirty_tables {
            if let Some(table) = self.tables.get(table_name) {
                catalog.tables.insert(table_name.clone(), table.clone());
            } else {
                catalog.tables.remove(table_name);
            }
        }
        for view_name in &self.dirty_views {
            if let Some(view) = self.views.get(view_name) {
                catalog.views.insert(view_name.clone(), view.clone());
            } else {
                catalog.views.remove(view_name);
            }
        }
        for view_name in &self.dirty_materialized_views {
            if let Some(view) = self.materialized_views.get(view_name) {
                catalog
                    .materialized_views
                    .insert(view_name.clone(), view.clone());
            } else {
                catalog.materialized_views.remove(view_name);
            }
        }
        for function_name in &self.dirty_functions {
            if let Some(function) = self.functions.get(function_name) {
                catalog
                    .functions
                    .insert(function_name.clone(), function.clone());
            } else {
                catalog.functions.remove(function_name);
            }
        }
        for sequence_name in &self.dirty_sequences {
            if let Some(sequence) = self.sequences.get(sequence_name) {
                catalog
                    .sequences
                    .insert(sequence_name.clone(), sequence.clone());
            } else {
                catalog.sequences.remove(sequence_name);
            }
        }
        for domain_name in &self.dirty_domains {
            if let Some(domain) = self.domains.get(domain_name) {
                catalog.domains.insert(domain_name.clone(), domain.clone());
            } else {
                catalog.domains.remove(domain_name);
            }
        }
        for publication_name in &self.dirty_publications {
            if let Some(publication) = self.publications.get(publication_name) {
                catalog
                    .publications
                    .insert(publication_name.clone(), publication.clone());
            } else {
                catalog.publications.remove(publication_name);
            }
        }
        for subscription_name in &self.dirty_subscriptions {
            if let Some(subscription) = self.subscriptions.get(subscription_name) {
                catalog
                    .subscriptions
                    .insert(subscription_name.clone(), subscription.clone());
            } else {
                catalog.subscriptions.remove(subscription_name);
            }
        }
        for role_name in &self.dirty_roles {
            if let Some(role) = self.roles.get(role_name) {
                catalog.roles.insert(role_name.clone(), role.clone());
            } else {
                catalog.roles.remove(role_name);
            }
        }
        for database_name in &self.dirty_databases {
            if let Some(database) = self.databases.get(database_name) {
                catalog
                    .databases
                    .insert(database_name.clone(), database.clone());
            } else {
                catalog.databases.remove(database_name);
            }
        }
        for tablespace_name in &self.dirty_tablespaces {
            if let Some(tablespace) = self.tablespaces.get(tablespace_name) {
                catalog
                    .tablespaces
                    .insert(tablespace_name.clone(), tablespace.clone());
            } else {
                catalog.tablespaces.remove(tablespace_name);
            }
        }
        for table_name in &self.dirty_table_acls {
            if let Some(acl) = self.table_acls.get(table_name) {
                catalog.table_acls.insert(table_name.clone(), acl.clone());
            } else {
                catalog.table_acls.remove(table_name);
            }
        }
        for database_name in &self.dirty_database_acls {
            if let Some(acl) = self.database_acls.get(database_name) {
                catalog
                    .database_acls
                    .insert(database_name.clone(), acl.clone());
            } else {
                catalog.database_acls.remove(database_name);
            }
        }
        for tablespace_name in &self.dirty_tablespace_acls {
            if let Some(acl) = self.tablespace_acls.get(tablespace_name) {
                catalog
                    .tablespace_acls
                    .insert(tablespace_name.clone(), acl.clone());
            } else {
                catalog.tablespace_acls.remove(tablespace_name);
            }
        }
        if self.dirty_default_table_acl {
            catalog.default_table_acl = self.default_table_acl.clone();
            self.dirty_default_table_acl = false;
        }
        if self.dirty_schema_acl {
            catalog.schema_acl = self.schema_acl.clone();
            self.dirty_schema_acl = false;
        }
        if self.dirty_schema {
            catalog.public_schema_exists = self.public_schema_exists;
            catalog.public_schema_implicit = self.public_schema_implicit;
            self.dirty_schema = false;
        }
        catalog.next_relation_oid = catalog.next_relation_oid.max(self.next_relation_oid);
        if self.dirty_indexes {
            let deleted_tables = self
                .dirty_tables
                .iter()
                .filter(|table_name| !self.tables.contains_key(*table_name))
                .cloned()
                .collect::<BTreeSet<_>>();
            let replaced_tables = self
                .dirty_tables
                .iter()
                .filter(|table_name| self.tables.contains_key(*table_name))
                .cloned()
                .collect::<BTreeSet<_>>();
            catalog.indexes.retain(|index| {
                !deleted_tables.contains(&index.table) && !replaced_tables.contains(&index.table)
            });
            for index in self
                .indexes
                .iter()
                .filter(|index| self.tables.contains_key(&index.table))
            {
                if let Some(existing) = catalog
                    .indexes
                    .iter_mut()
                    .find(|existing| existing.name == index.name)
                {
                    *existing = index.clone();
                } else {
                    catalog.indexes.push(index.clone());
                }
            }
            self.dirty_indexes = false;
        }
        for target in &self.dirty_comment_targets {
            if let Some(comment) = self.comments.get(target) {
                catalog.comments.insert(target.clone(), comment.clone());
            } else {
                catalog.comments.remove(target);
            }
        }
        self.dirty_comment_targets.clear();
        self.dirty_tables.clear();
        self.dirty_views.clear();
        self.dirty_materialized_views.clear();
        self.dirty_functions.clear();
        self.dirty_sequences.clear();
        self.dirty_domains.clear();
        self.dirty_publications.clear();
        self.dirty_subscriptions.clear();
        self.dirty_roles.clear();
        self.dirty_databases.clear();
        self.dirty_tablespaces.clear();
        self.dirty_table_acls.clear();
        self.dirty_database_acls.clear();
        self.dirty_tablespace_acls.clear();
    }

    fn close_extended_target(&mut self, target: DescribeTarget, name: &str) {
        match target {
            DescribeTarget::Statement => {
                if matches!(
                    self.prepared.get(name),
                    Some(PreparedStatement::Extended(_))
                ) {
                    self.prepared.remove(name);
                    self.portals
                        .retain(|_, portal| portal.statement_name != name);
                }
            }
            DescribeTarget::Portal => {
                self.portals.remove(name);
            }
        }
    }

    fn replace_extended_statement(&mut self, name: String, query: PreparedQuery) {
        self.prepared
            .insert(name.clone(), PreparedStatement::Extended(query));
        self.portals
            .retain(|_, portal| portal.statement_name != name);
    }

    fn replace_extended_portal(&mut self, name: String, portal: Portal) {
        self.portals.insert(name, portal);
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct Table {
    oid: u32,
    name: String,
    columns: Vec<CatalogColumn>,
    rows: Vec<Vec<SqlValue>>,
    check_constraints: Vec<CatalogCheckConstraint>,
    foreign_keys: Vec<CatalogForeignKey>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct RoleInfo {
    oid: u32,
    name: String,
    login: bool,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct DatabaseInfo {
    oid: u32,
    name: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct TablespaceInfo {
    oid: u32,
    name: String,
    location: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct View {
    oid: u32,
    name: String,
    query: gpu_db_protocol::Select,
    definition: String,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct MaterializedView {
    oid: u32,
    name: String,
    query: gpu_db_protocol::Select,
    definition: String,
    columns: Vec<CatalogColumn>,
    rows: Vec<Vec<SqlValue>>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct FunctionInfo {
    oid: u32,
    name: String,
    return_type: SqlType,
    body: String,
    acl: BTreeMap<String, BTreeSet<FunctionPrivilege>>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct Sequence {
    oid: u32,
    name: String,
    last_value: i64,
    is_called: bool,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct Domain {
    oid: u32,
    name: String,
    base_type: gpu_db_protocol::SqlType,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct Publication {
    oid: u32,
    name: String,
    all_tables: bool,
    tables: Vec<String>,
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct Subscription {
    oid: u32,
    name: String,
    connection: String,
    publications: Vec<String>,
    enabled: bool,
}

fn sequence_target_error(session: &Session, name: &str) -> Option<ErrorField> {
    if session.tables.contains_key(name)
        || session.views.contains_key(name)
        || session.materialized_views.contains_key(name)
    {
        return Some(ErrorField {
            code: "42809",
            message: "relation is not a sequence",
            position: None,
        });
    }
    if !session.sequences.contains_key(name) {
        return Some(ErrorField {
            code: "42P01",
            message: "sequence does not exist",
            position: None,
        });
    }
    None
}

fn next_sequence_value(sequence: &mut Sequence) -> Result<i64, ErrorField> {
    let value = if sequence.is_called {
        sequence.last_value.checked_add(1).ok_or(ErrorField {
            code: "2200H",
            message: "sequence value overflow",
            position: None,
        })?
    } else {
        sequence.last_value
    };
    sequence.last_value = value;
    sequence.is_called = true;
    Ok(value)
}

fn create_implicit_sequence(session: &mut Session, name: &str) -> Result<(), ErrorField> {
    if session.tables.contains_key(name)
        || session.views.contains_key(name)
        || session.materialized_views.contains_key(name)
        || session.sequences.contains_key(name)
    {
        return Err(ErrorField {
            code: "42P07",
            message: "relation already exists",
            position: None,
        });
    }
    let oid = session.next_relation_oid;
    session.next_relation_oid = session.next_relation_oid.checked_add(1).ok_or(ErrorField {
        code: "54000",
        message: "relation OID allocation exhausted",
        position: None,
    })?;
    session.sequences.insert(
        name.to_string(),
        Sequence {
            oid,
            name: name.to_string(),
            last_value: 1,
            is_called: false,
        },
    );
    session.mark_sequence_dirty(name.to_string());
    Ok(())
}

fn preflight_column_default_target(
    session: &Session,
    default: &ColumnDefault,
) -> Option<ErrorField> {
    match default {
        ColumnDefault::Literal(_) => None,
        ColumnDefault::SequenceNextVal {
            sequence,
            create_if_missing: true,
        } => {
            if session.tables.contains_key(sequence)
                || session.views.contains_key(sequence)
                || session.materialized_views.contains_key(sequence)
                || session.sequences.contains_key(sequence)
            {
                Some(ErrorField {
                    code: "42P07",
                    message: "relation already exists",
                    position: None,
                })
            } else {
                None
            }
        }
        ColumnDefault::SequenceNextVal {
            sequence,
            create_if_missing: false,
        } => sequence_target_error(session, sequence),
    }
}

fn resolve_column_domain_type(
    session: &Session,
    def: &mut gpu_db_protocol::ColumnDef,
) -> Result<u32, ErrorField> {
    if let Some(domain_name) = def.domain.as_ref() {
        let domain = session.domains.get(domain_name).ok_or(ErrorField {
            code: "42704",
            message: "type does not exist",
            position: None,
        })?;
        def.ty = domain.base_type;
        Ok(domain.oid)
    } else {
        Ok(def.ty.postgres_oid())
    }
}

fn add_column_default_supported(default: &ColumnDefault) -> bool {
    match default {
        ColumnDefault::Literal(_) => true,
        ColumnDefault::SequenceNextVal {
            create_if_missing, ..
        } => !create_if_missing,
    }
}

fn acl_relation_kind(session: &Session, relation: &str) -> Option<AclRelationKind> {
    if session.tables.contains_key(relation) {
        Some(AclRelationKind::Table)
    } else if session.views.contains_key(relation) {
        Some(AclRelationKind::View)
    } else if session.materialized_views.contains_key(relation) {
        Some(AclRelationKind::MaterializedView)
    } else if session.sequences.contains_key(relation) {
        Some(AclRelationKind::Sequence)
    } else {
        None
    }
}

fn role_exists(session: &Session, role: &str) -> bool {
    role == "postgres" || session.roles.contains_key(role)
}

fn database_exists(session: &Session, database: &str) -> bool {
    database == "postgres" || session.databases.contains_key(database)
}

fn tablespace_exists(session: &Session, tablespace: &str) -> bool {
    matches!(tablespace, "pg_default" | "pg_global") || session.tablespaces.contains_key(tablespace)
}

fn acl_grantee_error(session: &Session, grantee: &str) -> Option<ErrorField> {
    if grantee == "public" || role_exists(session, grantee) {
        None
    } else {
        Some(ErrorField {
            code: "42704",
            message: "role does not exist",
            position: None,
        })
    }
}

fn active_role(session: &Session) -> &str {
    session.current_role.as_deref().unwrap_or("postgres")
}

fn role_has_relation_privilege(
    session: &Session,
    relation: &str,
    privilege: TablePrivilege,
) -> bool {
    let role = active_role(session);
    if role == "postgres" {
        return true;
    }
    session.table_acls.get(relation).is_some_and(|acl| {
        acl.get(role)
            .is_some_and(|privileges| privileges.contains(&privilege))
            || acl
                .get("public")
                .is_some_and(|privileges| privileges.contains(&privilege))
    })
}

fn role_has_function_privilege(
    session: &Session,
    function: &str,
    privilege: FunctionPrivilege,
) -> bool {
    let role = active_role(session);
    if role == "postgres" {
        return true;
    }
    session.functions.get(function).is_some_and(|function| {
        function
            .acl
            .get(role)
            .is_some_and(|privileges| privileges.contains(&privilege))
            || function
                .acl
                .get("public")
                .is_some_and(|privileges| privileges.contains(&privilege))
    })
}

fn relation_permission_error(
    session: &Session,
    relation: &str,
    privilege: TablePrivilege,
) -> Option<ErrorField> {
    if role_has_relation_privilege(session, relation, privilege) {
        None
    } else {
        Some(ErrorField {
            code: "42501",
            message: "permission denied for relation",
            position: None,
        })
    }
}

fn role_has_schema_privilege(session: &Session, schema: &str, privilege: SchemaPrivilege) -> bool {
    let role = active_role(session);
    if role == "postgres" {
        return true;
    }
    if schema != "public" || !session.public_schema_exists {
        return false;
    }
    session
        .schema_acl
        .get(role)
        .is_some_and(|privileges| privileges.contains(&privilege))
        || session
            .schema_acl
            .get("public")
            .is_some_and(|privileges| privileges.contains(&privilege))
}

fn role_has_schema_usage(session: &Session, schema: &str) -> bool {
    if active_role(session) == "postgres" {
        return true;
    }
    if schema != "public" || !session.public_schema_exists {
        return false;
    }
    if session.schema_acl.is_empty() {
        return true;
    }
    role_has_schema_privilege(session, schema, SchemaPrivilege::Usage)
}

fn schema_permission_error(
    session: &Session,
    schema: &str,
    privilege: SchemaPrivilege,
) -> Option<ErrorField> {
    if role_has_schema_privilege(session, schema, privilege) {
        None
    } else {
        Some(ErrorField {
            code: "42501",
            message: "permission denied for schema",
            position: None,
        })
    }
}

fn schema_usage_permission_error(session: &Session, schema: &str) -> Option<ErrorField> {
    if role_has_schema_usage(session, schema) {
        None
    } else {
        Some(ErrorField {
            code: "42501",
            message: "permission denied for schema",
            position: None,
        })
    }
}

fn function_permission_error(session: &Session, function: &str) -> Option<ErrorField> {
    if role_has_function_privilege(session, function, FunctionPrivilege::Execute) {
        None
    } else {
        Some(ErrorField {
            code: "42501",
            message: "permission denied for function",
            position: None,
        })
    }
}

fn object_access_permission_error(
    session: &Session,
    relation: &str,
    privilege: TablePrivilege,
) -> Option<ErrorField> {
    schema_usage_permission_error(session, "public")
        .or_else(|| relation_permission_error(session, relation, privilege))
}

fn function_access_permission_error(session: &Session, function: &str) -> Option<ErrorField> {
    schema_usage_permission_error(session, "public")
        .or_else(|| function_permission_error(session, function))
}

fn role_has_dependencies(session: &Session, role: &str) -> bool {
    session.comments.contains_key(&CatalogCommentTarget::Role {
        role: role.to_string(),
    }) || session
        .table_acls
        .values()
        .any(|acl| acl.contains_key(role))
        || session
            .database_acls
            .values()
            .any(|acl| acl.contains_key(role))
        || session
            .tablespace_acls
            .values()
            .any(|acl| acl.contains_key(role))
        || session
            .functions
            .values()
            .any(|function| function.acl.contains_key(role))
        || session.schema_acl.contains_key(role)
        || session.default_table_acl.contains_key(role)
}

fn function_acl_target_error(session: &Session, function: &str) -> Option<ErrorField> {
    if session.functions.contains_key(function) {
        None
    } else {
        Some(ErrorField {
            code: "42883",
            message: "function does not exist",
            position: None,
        })
    }
}

fn relation_acl_target_error(
    session: &Session,
    relation: &str,
    kind: AclRelationKind,
) -> Option<ErrorField> {
    let Some(actual) = acl_relation_kind(session, relation) else {
        return Some(ErrorField {
            code: "42P01",
            message: "relation does not exist",
            position: None,
        });
    };
    let table_keyword_matches_relation = kind == AclRelationKind::Table
        && matches!(
            actual,
            AclRelationKind::Table | AclRelationKind::View | AclRelationKind::MaterializedView
        );
    if kind != AclRelationKind::Relation && kind != actual && !table_keyword_matches_relation {
        return Some(ErrorField {
            code: "42809",
            message: acl_relation_kind_error(kind),
            position: None,
        });
    }
    None
}

fn acl_relation_kind_error(kind: AclRelationKind) -> &'static str {
    match kind {
        AclRelationKind::Relation => "relation does not exist",
        AclRelationKind::Table => "relation is not a table",
        AclRelationKind::View => "relation is not a view",
        AclRelationKind::MaterializedView => "relation is not a materialized view",
        AclRelationKind::Sequence => "relation is not a sequence",
    }
}

fn grant_relation_acl(
    session: &mut Session,
    relation: &str,
    kind: AclRelationKind,
    grantee: &str,
    privileges: &[TablePrivilege],
) -> Result<(), ErrorField> {
    if let Some(error) = acl_grantee_error(session, grantee) {
        return Err(error);
    }
    if let Some(error) = relation_acl_target_error(session, relation, kind) {
        return Err(error);
    }
    let grantee_acl = session
        .table_acls
        .entry(relation.to_string())
        .or_default()
        .entry(grantee.to_string())
        .or_default();
    for privilege in privileges {
        grantee_acl.insert(*privilege);
    }
    session.mark_table_acl_dirty(relation.to_string());
    Ok(())
}

fn revoke_relation_acl(
    session: &mut Session,
    relation: &str,
    kind: AclRelationKind,
    grantee: &str,
    privileges: &[TablePrivilege],
) -> Result<(), ErrorField> {
    if let Some(error) = acl_grantee_error(session, grantee) {
        return Err(error);
    }
    if let Some(error) = relation_acl_target_error(session, relation, kind) {
        return Err(error);
    }
    let remove_table_acl = if let Some(acl) = session.table_acls.get_mut(relation) {
        if let Some(grantee_acl) = acl.get_mut(grantee) {
            for privilege in privileges {
                grantee_acl.remove(privilege);
            }
            if grantee_acl.is_empty() {
                acl.remove(grantee);
            }
        }
        acl.is_empty()
    } else {
        false
    };
    if remove_table_acl {
        session.table_acls.remove(relation);
    }
    session.mark_table_acl_dirty(relation.to_string());
    Ok(())
}

fn grant_function_acl(
    session: &mut Session,
    function: &str,
    grantee: &str,
    privileges: &[FunctionPrivilege],
) -> Result<(), ErrorField> {
    if let Some(error) = acl_grantee_error(session, grantee) {
        return Err(error);
    }
    if let Some(error) = function_acl_target_error(session, function) {
        return Err(error);
    }
    let acl = session
        .functions
        .get_mut(function)
        .expect("function ACL target preflighted")
        .acl
        .entry(grantee.to_string())
        .or_default();
    for privilege in privileges {
        acl.insert(*privilege);
    }
    session.mark_function_dirty(function.to_string());
    Ok(())
}

fn revoke_function_acl(
    session: &mut Session,
    function: &str,
    grantee: &str,
    privileges: &[FunctionPrivilege],
) -> Result<(), ErrorField> {
    if let Some(error) = acl_grantee_error(session, grantee) {
        return Err(error);
    }
    if let Some(error) = function_acl_target_error(session, function) {
        return Err(error);
    }
    let function_info = session
        .functions
        .get_mut(function)
        .expect("function ACL target preflighted");
    if let Some(acl) = function_info.acl.get_mut(grantee) {
        for privilege in privileges {
            acl.remove(privilege);
        }
        if acl.is_empty() {
            function_info.acl.remove(grantee);
        }
    }
    session.mark_function_dirty(function.to_string());
    Ok(())
}

fn schema_acl_target_error(session: &Session, schema: &str) -> Option<ErrorField> {
    if schema != "public" || !session.public_schema_exists {
        Some(ErrorField {
            code: "3F000",
            message: "schema does not exist",
            position: None,
        })
    } else {
        None
    }
}

fn grant_schema_acl(
    session: &mut Session,
    schema: &str,
    grantee: &str,
    privileges: &[SchemaPrivilege],
) -> Result<(), ErrorField> {
    if let Some(error) = acl_grantee_error(session, grantee) {
        return Err(error);
    }
    if let Some(error) = schema_acl_target_error(session, schema) {
        return Err(error);
    }
    let acl = session.schema_acl.entry(grantee.to_string()).or_default();
    for privilege in privileges {
        acl.insert(*privilege);
    }
    session.mark_schema_acl_dirty();
    Ok(())
}

fn revoke_schema_acl(
    session: &mut Session,
    schema: &str,
    grantee: &str,
    privileges: &[SchemaPrivilege],
) -> Result<(), ErrorField> {
    if let Some(error) = acl_grantee_error(session, grantee) {
        return Err(error);
    }
    if let Some(error) = schema_acl_target_error(session, schema) {
        return Err(error);
    }
    if let Some(acl) = session.schema_acl.get_mut(grantee) {
        for privilege in privileges {
            acl.remove(privilege);
        }
        if acl.is_empty() {
            session.schema_acl.remove(grantee);
        }
    }
    session.mark_schema_acl_dirty();
    Ok(())
}

fn grant_default_table_acl(
    session: &mut Session,
    grantee: &str,
    privileges: &[TablePrivilege],
) -> Result<(), ErrorField> {
    if let Some(error) = acl_grantee_error(session, grantee) {
        return Err(error);
    }
    let acl = session
        .default_table_acl
        .entry(grantee.to_string())
        .or_default();
    for privilege in privileges {
        acl.insert(*privilege);
    }
    session.mark_default_table_acl_dirty();
    Ok(())
}

fn revoke_default_table_acl(
    session: &mut Session,
    grantee: &str,
    privileges: &[TablePrivilege],
) -> Result<(), ErrorField> {
    if let Some(error) = acl_grantee_error(session, grantee) {
        return Err(error);
    }
    if let Some(acl) = session.default_table_acl.get_mut(grantee) {
        for privilege in privileges {
            acl.remove(privilege);
        }
        if acl.is_empty() {
            session.default_table_acl.remove(grantee);
        }
    }
    session.mark_default_table_acl_dirty();
    Ok(())
}

fn grant_database_acl(
    session: &mut Session,
    database: &str,
    grantee: &str,
    privileges: &[DatabasePrivilege],
) -> Result<(), ErrorField> {
    if let Some(error) = acl_grantee_error(session, grantee) {
        return Err(error);
    }
    if !session.databases.contains_key(database) {
        return Err(ErrorField {
            code: "3D000",
            message: "database does not exist",
            position: None,
        });
    }
    let acl = session
        .database_acls
        .entry(database.to_string())
        .or_default()
        .entry(grantee.to_string())
        .or_default();
    for privilege in privileges {
        acl.insert(*privilege);
    }
    session.mark_database_acl_dirty(database.to_string());
    Ok(())
}

fn revoke_database_acl(
    session: &mut Session,
    database: &str,
    grantee: &str,
    privileges: &[DatabasePrivilege],
) -> Result<(), ErrorField> {
    if let Some(error) = acl_grantee_error(session, grantee) {
        return Err(error);
    }
    if !session.databases.contains_key(database) {
        return Err(ErrorField {
            code: "3D000",
            message: "database does not exist",
            position: None,
        });
    }
    let remove_acl = if let Some(acl) = session.database_acls.get_mut(database) {
        if let Some(grantee_acl) = acl.get_mut(grantee) {
            for privilege in privileges {
                grantee_acl.remove(privilege);
            }
            if grantee_acl.is_empty() {
                acl.remove(grantee);
            }
        }
        acl.is_empty()
    } else {
        false
    };
    if remove_acl {
        session.database_acls.remove(database);
    }
    session.mark_database_acl_dirty(database.to_string());
    Ok(())
}

