fn publication_table_target_error(session: &Session, table: &str) -> Option<ErrorField> {
    if session.views.contains_key(table)
        || session.materialized_views.contains_key(table)
        || session.sequences.contains_key(table)
    {
        return Some(ErrorField {
            code: "42809",
            message: "relation is not a table",
            position: None,
        });
    }
    if !session.tables.contains_key(table) {
        return Some(ErrorField {
            code: "42P01",
            message: "relation does not exist",
            position: None,
        });
    }
    None
}

fn create_publication(
    session: &mut Session,
    name: String,
    target: PublicationTarget,
) -> Result<(), ErrorField> {
    if session.publications.contains_key(&name) {
        return Err(ErrorField {
            code: "42710",
            message: "publication already exists",
            position: None,
        });
    }
    let (all_tables, tables) = match target {
        PublicationTarget::AllTables => (true, Vec::new()),
        PublicationTarget::Tables(tables) => {
            let mut seen = BTreeSet::new();
            for table in &tables {
                if !seen.insert(table.clone()) {
                    return Err(ErrorField {
                        code: "42710",
                        message: "publication table specified more than once",
                        position: None,
                    });
                }
                if let Some(error) = publication_table_target_error(session, table) {
                    return Err(error);
                }
            }
            (false, tables)
        }
    };
    let oid = session.next_relation_oid;
    session.next_relation_oid = session.next_relation_oid.checked_add(1).ok_or(ErrorField {
        code: "54000",
        message: "publication OID allocation exhausted",
        position: None,
    })?;
    session.publications.insert(
        name.clone(),
        Publication {
            oid,
            name: name.clone(),
            all_tables,
            tables,
        },
    );
    session.mark_publication_dirty(name);
    Ok(())
}

fn drop_publication(
    session: &mut Session,
    names: &[String],
    if_exists: bool,
) -> Result<(), ErrorField> {
    let mut seen = BTreeSet::new();
    for name in names {
        if !seen.insert(name.clone()) {
            return Err(ErrorField {
                code: "42710",
                message: "publication specified more than once",
                position: None,
            });
        }
        if !if_exists && !session.publications.contains_key(name) {
            return Err(ErrorField {
                code: "42704",
                message: "publication does not exist",
                position: None,
            });
        }
    }
    for name in names {
        session.publications.remove(name);
        let target = CatalogCommentTarget::Publication {
            publication: name.clone(),
        };
        session.comments.remove(&target);
        session.mark_comment_dirty(target);
        session.mark_publication_dirty(name.clone());
    }
    Ok(())
}

fn create_subscription(
    session: &mut Session,
    name: String,
    connection: String,
    publications: Vec<String>,
) -> Result<(), ErrorField> {
    if session.subscriptions.contains_key(&name) {
        return Err(ErrorField {
            code: "42710",
            message: "subscription already exists",
            position: None,
        });
    }
    let mut seen = BTreeSet::new();
    for publication in &publications {
        if !seen.insert(publication.clone()) {
            return Err(ErrorField {
                code: "42710",
                message: "subscription publication specified more than once",
                position: None,
            });
        }
        if !session.publications.contains_key(publication) {
            return Err(ErrorField {
                code: "42704",
                message: "publication does not exist",
                position: None,
            });
        }
    }
    let oid = session.next_relation_oid;
    session.next_relation_oid = session.next_relation_oid.checked_add(1).ok_or(ErrorField {
        code: "54000",
        message: "subscription OID allocation exhausted",
        position: None,
    })?;
    session.subscriptions.insert(
        name.clone(),
        Subscription {
            oid,
            name: name.clone(),
            connection,
            publications,
            enabled: false,
        },
    );
    session.mark_subscription_dirty(name);
    Ok(())
}

fn drop_subscription(
    session: &mut Session,
    names: &[String],
    if_exists: bool,
) -> Result<(), ErrorField> {
    let mut seen = BTreeSet::new();
    for name in names {
        if !seen.insert(name.clone()) {
            return Err(ErrorField {
                code: "42710",
                message: "subscription specified more than once",
                position: None,
            });
        }
        if !if_exists && !session.subscriptions.contains_key(name) {
            return Err(ErrorField {
                code: "42704",
                message: "subscription does not exist",
                position: None,
            });
        }
    }
    for name in names {
        session.subscriptions.remove(name);
        let target = CatalogCommentTarget::Subscription {
            subscription: name.clone(),
        };
        session.comments.remove(&target);
        session.mark_comment_dirty(target);
        session.mark_subscription_dirty(name.clone());
    }
    Ok(())
}

fn add_check_constraint_to_session(
    session: &mut Session,
    table_name: &str,
    constraint_name: String,
    filter: SelectFilter,
) -> Result<(), ErrorField> {
    if session
        .indexes
        .iter()
        .any(|index| index.name == constraint_name)
        || session.tables.values().any(|table| {
            table
                .check_constraints
                .iter()
                .any(|constraint| constraint.name == constraint_name)
                || table
                    .foreign_keys
                    .iter()
                    .any(|constraint| constraint.name == constraint_name)
        })
        || session.tables.contains_key(&constraint_name)
        || session.views.contains_key(&constraint_name)
        || session.materialized_views.contains_key(&constraint_name)
        || session.sequences.contains_key(&constraint_name)
    {
        return Err(ErrorField {
            code: "42710",
            message: "constraint already exists",
            position: None,
        });
    }
    let Some(table) = session.tables.get(table_name) else {
        return Err(ErrorField {
            code: "42P01",
            message: "relation does not exist",
            position: None,
        });
    };
    let Some(column) = table
        .columns
        .iter()
        .find(|column| column.def.name == filter.column)
    else {
        return Err(ErrorField {
            code: "42703",
            message: "column does not exist",
            position: None,
        });
    };
    if !sql_value_matches_type(&filter.value, column.def.ty) {
        return Err(ErrorField {
            code: "42804",
            message: "column type mismatch",
            position: None,
        });
    }
    let mut candidate = table.clone();
    candidate.check_constraints.push(CatalogCheckConstraint {
        name: constraint_name,
        table: table_name.to_string(),
        column: filter.column,
        op: filter.op,
        value: filter.value,
    });
    validate_check_constraints(&candidate)?;
    session
        .tables
        .get_mut(table_name)
        .expect("table existence checked")
        .check_constraints = candidate.check_constraints;
    session.mark_table_dirty(table_name.to_string());
    Ok(())
}

fn evaluate_column_default(
    session: &mut Session,
    default: &ColumnDefault,
) -> Result<SqlValue, ErrorField> {
    match default {
        ColumnDefault::Literal(value) => Ok(value.clone()),
        ColumnDefault::SequenceNextVal { sequence, .. } => {
            if let Some(error) = sequence_target_error(session, sequence) {
                return Err(error);
            }
            let sequence_state = session
                .sequences
                .get_mut(sequence)
                .expect("sequence target checked");
            let value = next_sequence_value(sequence_state)?;
            session.currval_sequences.insert(sequence.clone(), value);
            session.mark_sequence_dirty(sequence.clone());
            i32::try_from(value)
                .map(SqlValue::Int4)
                .map_err(|_| ErrorField {
                    code: "22003",
                    message: "sequence value is out of range for int4 default",
                    position: None,
                })
        }
    }
}

