                {
                    return write_error(stream, &error);
                }
                let sequence = session
                    .sequences
                    .get_mut(&nextval.name)
                    .expect("sequence target checked");
                let value = match next_sequence_value(sequence) {
                    Ok(value) => value,
                    Err(error) => return write_error(stream, &error),
                };
