fn sql_type_alignment_code(ty: SqlType) -> &'static str {
    match ty {
        SqlType::Int2 => "s",
        SqlType::Int4 => "i",
        SqlType::Int8 => "d",
        SqlType::Numeric { .. } => "i",
        SqlType::Bool => "c",
        SqlType::Text => "i",
        SqlType::Date => "i",
        SqlType::Timestamp => "d",
        SqlType::Uuid => "c",
    }
}

